INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('K5-1-u6-C1','kor',5,1,'u6',1,'비유적 표현의 뜻 — 어떤 대상을 비슷한 점이 있는 다른 대상에 빗대어 표현하는 것이 비유적 표현이며, 사실을 있는 그대로 적거나 어려운 낱말을 쓰는 것과는 다르다',ARRAY['6국05-02 문학']::text[],1),
('K5-1-u6-C2','kor',5,1,'u6',1,'실제로 그렇다는 말이 아니다 — 얼굴이 홍당무가 됐다는 말은 얼굴이 정말 홍당무로 바뀌었다는 뜻이 아니라, 어떤 모습인지 더 잘 떠오르게 견주어 말한 것이다',ARRAY['6국05-02 문학']::text[],2),
('K5-1-u6-C3','kor',5,1,'u6',1,'빗대어 표현하면 좋은 점 — 빗대어 표현하면 익숙한 대상을 새롭게 느끼게 하고, 장면을 생생하게 떠올리게 하며, 말하는 이의 마음이 잘 전해진다',ARRAY['6국05-02 문학']::text[],3),
('K5-1-u6-C4','kor',5,1,'u6',1,'빗댄 것과 대상의 비슷한 점 — 지우개를 작은 눈사람에 빗댄 까닭은 둘 다 하얗고 지날수록 점점 작아진다는 비슷한 점이 있기 때문이다',ARRAY['6국05-02 문학']::text[],4),
('K5-1-u6-C5','kor',5,1,'u6',1,'비유는 일상 속에도 있다 — 비유는 시에만 있는 것이 아니라 노랫말, 「발이 넓다」 같은 관용어, 「티끌 모아 태산」 같은 속담처럼 일상의 말에도 들어 있다',ARRAY['6국05-02 문학']::text[],5),
('K5-1-u6-C6','kor',5,1,'u6',1,'인상적인 부분의 뜻 — 작품을 읽고 유난히 마음에 남는 부분, 곧 마음이 움직인 곳이 인상적인 부분이며 사람마다 다르고 그 까닭도 저마다 다르다',ARRAY['6국05-04 문학']::text[],6),
('K5-1-u6-C7','kor',5,1,'u6',1,'이 단원의 두 갈래 — 이 단원에서는 비유적 표현을 알고 시 낭송하기와 인상적인 부분을 중심으로 이야기 감상하기를 배운다',ARRAY['6국05-02 문학']::text[],7),
('K5-1-u6-C8','kor',5,1,'u6',2,'시에서 표현하는 대상 찾기 — 시를 읽을 때는 무엇을 무엇에 빗대었는지부터 찾으며, 「내 마음은 유리병」에서 표현하는 대상은 내 마음이고 빗댄 것은 유리병이다',ARRAY['6국05-02 문학']::text[],8),
('K5-1-u6-C9','kor',5,1,'u6',2,'은유법 — 「내 마음은 유리병」처럼 견주는 말 없이 「……은 ……이다」 꼴로 바로 그것이라고 말하며 빗대는 방법이 은유법이다',ARRAY['6국05-02 문학']::text[],9),
('K5-1-u6-C10','kor',5,1,'u6',2,'직유법 — 「우산처럼 기울어」처럼 견주는 말을 써서 두 대상을 직접 견주는 방법이 직유법이며, 견주는 말이 겉으로 드러난다',ARRAY['6국05-02 문학']::text[],10),
('K5-1-u6-C11','kor',5,1,'u6',2,'직유에 쓰이는 견주는 말 — 직유법에는 같이 · 처럼 · 듯이뿐 아니라 「우산 같은 친구」의 같은, 그리고 만큼처럼 견주는 말이 쓰인다',ARRAY['6국05-02 문학']::text[],11),
('K5-1-u6-C12','kor',5,1,'u6',2,'비슷한 점이 있어야 마음에 닿는다 — 비유는 아무것에나 빗대는 것이 아니라 두 대상 사이에 비슷한 점이 있어야 하며, 우산 같은 친구는 제가 젖으면서도 남에게 기울어 주는 모습이 닮았다',ARRAY['6국05-02 문학']::text[],12),
('K5-1-u6-C13','kor',5,1,'u6',2,'꼴이 같아도 은유가 아닐 수 있다 — 「내 동생은 삼 학년이다」와 「내 동생은 작은 태풍이다」는 꼴이 같지만 앞은 사실이고 뒤만 비유이므로, 꼴이 아니라 서로 다른 종류의 두 대상이 겹쳐졌는지를 본다',ARRAY['6국05-02 문학']::text[],13),
('K5-1-u6-C14','kor',5,1,'u6',2,'비유가 아닌 문장 — 「교실에 나무 화분이 있다」처럼 다른 것에 빗대지 않고 사실을 그대로 말한 문장은 비유가 아니며, 다른 것에 빗대었는가가 판별 기준이다',ARRAY['6국05-02 문학']::text[],14),
('K5-1-u6-C15','kor',5,1,'u6',2,'방법을 바꾸면 느낌이 달라진다 — 같은 비유도 직유로 쓰면 조심스럽게 견주고 은유로 쓰면 단번에 겹쳐 놓아, 방법에 따라 느낌이 달라진다',ARRAY['6국05-02 문학']::text[],15),
('K5-1-u6-C16','kor',5,1,'u6',2,'이름을 외우는 것이 목적은 아니다 — 은유법 · 직유법의 이름을 외우는 것보다 시를 읽다가 두 대상을 겹쳐 놓은 표현을 알아보고 그 느낌을 감상하는 것이 먼저다',ARRAY['6국05-02 문학']::text[],16),
('K5-1-u6-C17','kor',5,1,'u6',4,'시의 내용 알기 — 「나는 아직 새벽」의 말하는 이는 자신을 새벽에 빗대어 아직 자라는 중인 시기를 지나고 있다고 말한다',ARRAY['6국05-02 문학']::text[],17),
('K5-1-u6-C18','kor',5,1,'u6',4,'비유적 표현의 뜻 풀기 — 「한낮이길 바라지」는 빨리 다 자라기를 바란다는 뜻이고, 「종달새처럼 크게 울게」는 때가 되면 힘껏 나를 펼치겠다는 뜻이다',ARRAY['6국05-02 문학']::text[],18),
('K5-1-u6-C19','kor',5,1,'u6',4,'그것에 빗댄 까닭 — 자라는 시기를 하루의 시간에 빗댄 것은 자라는 일이 새벽 · 아침 · 한낮처럼 차례대로 오고 건너뛸 수 없다는 점이 닮았기 때문이다',ARRAY['6국05-02 문학']::text[],19),
('K5-1-u6-C20','kor',5,1,'u6',4,'말하는 이의 마음 헤아리기 — 어른들이 벌써 한낮이길 바랄 때 「하지만 나는 아직 새벽」을 되풀이한 데서 재촉받는 것이 서운하고 답답한 마음을 헤아린다',ARRAY['6국05-02 문학']::text[],20),
('K5-1-u6-C21','kor',5,1,'u6',4,'시를 낭송하는 방법 — 시는 분위기를 생각하며, 말하는 이의 처지나 마음을 상상하며, 어울리는 몸짓이나 표정으로, 친구와 번갈아 가며 낭송할 수 있다',ARRAY['6국05-02 문학']::text[],21),
('K5-1-u6-C22','kor',5,1,'u6',4,'낭송할 때 살릴 것 — 낭송할 때는 시의 분위기, 말하는 이의 마음, 되풀이되는 말의 리듬을 살리며, 빠른 속도나 큰 목소리가 목표가 아니다',ARRAY['6국05-02 문학']::text[],22),
('K5-1-u6-C23','kor',5,1,'u6',4,'끊어 읽기 — 어디서 쉬느냐에 따라 힘이 실리는 말이 달라지므로, 되풀이되는 말은 조금 더 천천히, 마음이 실린 말은 한 박자 쉬고 읽는다',ARRAY['6국05-02 문학']::text[],23),
('K5-1-u6-C24','kor',5,1,'u6',4,'시의 분위기에 맞는 낭송 — 재촉받으면서도 스스로를 다독이는 「나는 아직 새벽」은 차분하게, 되풀이되는 말을 조용히 되뇌듯이 낭송하는 것이 어울린다',ARRAY['6국05-02 문학']::text[],24),
('K5-1-u6-C25','kor',5,1,'u6',4,'여러 번 되풀이해 읽기 — 시는 한 번 읽고 끝내는 글이 아니어서 혼자도, 함께도 여러 번 소리 내어 읽을수록 처음에 지나친 뜻이 보이며, 낭송은 결과보다 그 과정이 중요하다',ARRAY['6국05-02 문학']::text[],25),
('K5-1-u6-C26','kor',5,1,'u6',4,'자신과 관련지어 감상하기 — 말하는 이가 자신을 새벽에 빗댄 것처럼 지금의 나를 무엇에 빗댈지 그 까닭과 함께 떠올리면 시가 내 이야기가 되고 나를 조금 더 알게 된다',ARRAY['6국05-02 문학']::text[],26),
('K5-1-u6-C27','kor',5,1,'u6',6,'시로 쓸 대상 고르기 — 시는 거창하거나 화려한 말이 아니라 겪은 일에서 오므로, 내가 직접 보고 겪어서 특징을 떠올릴 수 있는 대상을 고른다',ARRAY['6국05-02 문학']::text[],27),
('K5-1-u6-C28','kor',5,1,'u6',6,'대상을 살펴 떠올리기 — 시로 쓸 대상을 정하면 대상의 특징, 대상과 관련한 경험, 그때의 생각이나 느낌을 함께 떠올린다',ARRAY['6국05-02 문학']::text[],28),
('K5-1-u6-C29','kor',5,1,'u6',6,'보이지 않는 특징 — 겉모습만 보면 비유가 얕아지므로, 사진으로 찍을 수 없는 하는 일이나 태도 같은 보이지 않는 특징도 살핀다',ARRAY['6국05-02 문학']::text[],29),
('K5-1-u6-C30','kor',5,1,'u6',6,'비유를 만드는 차례 — 시로 쓸 대상 → 대상의 특징 → 비유할 대상 → 비슷한 점 → 비유적 표현의 차례로 비유를 만든다',ARRAY['6국05-02 문학']::text[],30),
('K5-1-u6-C31','kor',5,1,'u6',6,'좋은 비유의 조건 — 좋은 비유는 두 대상 사이에 비슷한 점이 있고, 그렇게 빗댄 까닭을 말할 수 있으며, 담고 싶은 뜻이나 마음이 함께 전해진다',ARRAY['6국05-02 문학']::text[],31),
('K5-1-u6-C32','kor',5,1,'u6',6,'비유는 많을수록 좋은 것이 아니다 — 비유를 많이 넣는 것이 목적이 아니라 대상의 특징이 잘 드러나는 비유 하나가 흩어진 비유 여럿보다 오래 남는다',ARRAY['6국05-02 문학']::text[],32),
('K5-1-u6-C33','kor',5,1,'u6',6,'감상 쪽지 쓰기 — 감상 쪽지에는 어느 표현이 왜 좋았는지와 더 좋은 생각을 적으며, 쪽지는 점수를 매기는 것이 아니라 다음 시를 돕는 것이다',ARRAY['6국05-02 문학']::text[],33),
('K5-1-u6-C34','kor',5,1,'u6',6,'같은 대상도 빗대는 것은 저마다 다르다 — 같은 대상을 골라도 무엇에 빗대는지는 사람마다 다르며, 그 차이가 그 사람이 대상을 보는 눈이다',ARRAY['6국05-02 문학']::text[],34),
('K5-1-u6-C35','kor',5,1,'u6',8,'이야기의 내용 알기 — 「할머니의 라디오」에서 재하는 정전이 난 밤 어둠 속에서 할머니의 이야기를 오래 들은 뒤로 라디오 소리가 거슬리지 않게 되었다',ARRAY['6국05-02 문학']::text[],35),
('K5-1-u6-C36','kor',5,1,'u6',8,'이야기 속 비유적 표현 찾기 — 이야기에서도 「오래된 이불처럼」 · 「두꺼운 담요 같았다」처럼 다른 것에 빗대어 그린 표현을 찾을 수 있으며, 사실을 적은 문장은 비유가 아니다',ARRAY['6국05-02 문학']::text[],36),
('K5-1-u6-C37','kor',5,1,'u6',8,'비유가 만드는 느낌 — 「두꺼운 담요 같은 어둠」은 답답하고 조금 무서운 느낌을, 「낮은 강물처럼 흘러온 목소리」는 잔잔하고 마음을 놓게 하는 느낌을 만든다',ARRAY['6국05-02 문학']::text[],37),
('K5-1-u6-C38','kor',5,1,'u6',8,'이야기에서 비유를 쓰면 좋은 점 — 이야기에 비유적 표현을 쓰면 장면이 생생해지고, 설명하지 않아도 인물의 마음이 함께 전해진다',ARRAY['6국05-02 문학']::text[],38),
('K5-1-u6-C39','kor',5,1,'u6',8,'비유 찾기가 목적은 아니다 — 비유적 표현만 골라내다 보면 이야기 전체를 놓치기 쉬우므로, 누가 무엇을 겪었고 마음이 어떻게 달라졌는지를 먼저 살핀다',ARRAY['6국05-02 문학']::text[],39),
('K5-1-u6-C40','kor',5,1,'u6',8,'인상적인 부분 고르기 — 인상적인 부분은 가장 중요한 장면이 아니라 내 마음이 움직인 장면이며, 인물의 말이나 행동 · 사건 · 배경 · 표현 가운데에서 고른다',ARRAY['6국05-04 문학']::text[],40),
('K5-1-u6-C41','kor',5,1,'u6',8,'까닭과 근거를 대며 말하기 — 인상적인 부분을 고른 뒤에는 작품의 어느 대목 때문에 그렇게 느꼈는지 근거를 함께 말하며, 근거를 대면 감상이 내 의견이 된다',ARRAY['6국05-04 문학']::text[],41),
('K5-1-u6-C42','kor',5,1,'u6',8,'내 삶과 이어 감상 나누기 — 작품을 읽고 놓치고 지낸 일은 없었는지처럼 내 삶과 이어 생각을 나누면 작품이 더 오래 남는다',ARRAY['6국05-04 문학']::text[],42),
('K5-1-u6-C43','kor',5,1,'u6',10,'신화의 뜻 — 신화는 아주 오래전부터 입에서 입으로 전해 온 이야기로, 나라가 어떻게 세워졌는지나 세상이 어떻게 생겼는지를 놀라운 사건으로 풀어낸다',ARRAY['6국05-04 문학']::text[],43),
('K5-1-u6-C44','kor',5,1,'u6',10,'신화의 흐름 알기 — 주몽 이야기는 알에서 태어남 → 뛰어난 활 솜씨와 태자의 시기 → 좋은 말을 마련해 떠남 → 자라와 물고기의 도움으로 강을 건너 고구려를 세움의 차례로 흐른다',ARRAY['6국05-04 문학']::text[],44),
('K5-1-u6-C45','kor',5,1,'u6',10,'신화 속 낱말의 뜻 — 도읍은 한 나라의 중앙 정부가 있는 곳, 태자는 임금의 뒤를 이을 아들, 후환은 뒷날 생기는 걱정과 근심, 단연은 여럿 가운데 뚜렷하게라는 뜻이다',ARRAY['6국05-04 문학']::text[],45),
('K5-1-u6-C46','kor',5,1,'u6',10,'신화 속 비유적 표현 — 「그림자처럼 따라다닌 햇빛」 · 「갈대처럼 여윈 말」처럼 신화에도 비유적 표현이 쓰여 장면이 또렷해진다',ARRAY['6국05-02 문학']::text[],46),
('K5-1-u6-C47','kor',5,1,'u6',10,'신화의 특징 — 신화에는 비범한 탄생, 남다른 재주, 시련과 뜻밖의 도움, 나라의 시작이 자주 나타난다',ARRAY['6국05-04 문학']::text[],47),
('K5-1-u6-C48','kor',5,1,'u6',10,'여러 신화의 닮은 점 — 주몽 · 박혁거세 · 프로메테우스 이야기에는 보통 사람과 다른 특별한 인물이 나오고, 놀라운 사건이 일어나며, 무언가의 시작을 설명한다는 닮은 점이 있다',ARRAY['6국05-04 문학']::text[],48),
('K5-1-u6-C49','kor',5,1,'u6',10,'같은 장면도 해석이 갈린다 — 고르는 장면이 사람마다 다를 뿐 아니라 같은 장면을 두고도 다르게 새길 수 있으며, 감상 나누기는 누구의 감상이 맞는지 가리는 일이 아니다',ARRAY['6국05-04 문학']::text[],49),
('K5-1-u6-C50','kor',5,1,'u6',12,'책갈피를 만드는 차례 — 읽은 작품을 고르고 → 비유적 표현을 찾아 → 앞면에 표현, 뒷면에 어울리는 그림을 넣고 → 끈을 묶어 책갈피를 완성한다',ARRAY['6국05-02 문학']::text[],50),
('K5-1-u6-C51','kor',5,1,'u6',12,'책갈피에 담을 표현 — 책갈피에는 한 줄만으로도 장면이 떠오르는 비유적 표현을 고르며, 「오늘은 화요일이다」처럼 사실만 적은 문장은 알맞지 않다',ARRAY['6국05-02 문학']::text[],51),
('K5-1-u6-C52','kor',5,1,'u6',12,'그림은 표현이 만든 장면을 담는다 — 책갈피 뒷면의 그림은 표현을 다시 설명하는 것이 아니라 그 표현이 만든 장면을 담는 것이다',ARRAY['6국05-02 문학']::text[],52),
('K5-1-u6-C53','kor',5,1,'u6',12,'만들 때 살필 것 — 책갈피는 작으므로 표현은 한두 줄만 옮기고 글씨는 또렷하게, 색은 분위기에 맞추며, 가져온 표현이라면 작품 제목과 지은이를 적는다',ARRAY['6국05-02 문학']::text[],53),
('K5-1-u6-C54','kor',5,1,'u6',12,'책갈피를 소개하는 말 — 완성한 책갈피를 소개할 때는 고른 표현과 그것을 고른 까닭을 함께 말한다',ARRAY['6국05-02 문학']::text[],54),
('K5-1-u6-C55','kor',5,1,'u6',12,'빗대어 말하면 스스로 깨닫게 된다 — 「조개와 황새」의 신하가 「싸우지 마십시오」 대신 이야기를 들려준 것처럼, 빗대어 말하면 듣는 사람이 스스로 깨닫게 되므로 비유는 시만의 기술이 아니라 말의 방법이다',ARRAY['6국05-02 문학']::text[],55),
('K5-1-u6-C56','kor',5,1,'u6',12,'이야기에 담긴 뜻 헤아리기 — 「조개와 황새」는 두 나라가 다투면 지켜보던 다른 나라만 이롭다는 뜻을 조개 · 황새 · 어부에 빗대어 담았다',ARRAY['6국05-04 문학']::text[],56),
('K5-1-u6-C57','kor',5,1,'u6',12,'잘 듣는 방법 — 말하는 사람을 보며 귀 기울여 듣고, 정리하며 듣고, 모르는 말은 질문하며 듣고, 이해한 내용이 맞는지 확인하며 들으며, 잘 듣기는 가만히 있는 일이 아니라 움직이는 일이다 (기초 다지기)',ARRAY['기초 다지기(잘 듣는 방법)']::text[],57),
('K5-1-u6-C58','kor',5,1,'u6',12,'피해야 할 듣기 태도 — 내용이 많다고 흘려듣기, 듣고 싶은 부분만 골라 듣기, 실수나 부족한 점만 따지며 듣기, 모르면서 묻지 않고 넘어가기는 피한다 (기초 다지기)',ARRAY['기초 다지기(잘 듣는 방법)']::text[],58)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('K5-1-u6-X01','kor',5,'u6',ARRAY['K5-1-u6-C1']::text[],'비유적 표현을 사실을 있는 그대로 자세히 적는 것이나 어려운 낱말을 많이 쓰는 것으로 여긴다','비슷한 것에 빗대기'),
('K5-1-u6-X02','kor',5,'u6',ARRAY['K5-1-u6-C2']::text[],'비유적 표현을 실제로 그렇게 바뀌었다는 말로 받아들이거나, 사실이 아니니 거짓말이라고 여긴다','견주어 말한 것'),
('K5-1-u6-X03','kor',5,'u6',ARRAY['K5-1-u6-C3']::text[],'빗대어 표현하는 까닭을 글을 길게 늘이거나 어려워 보이게 하려는 것으로 여긴다','새롭게 · 생생하게 · 마음'),
('K5-1-u6-X04','kor',5,'u6',ARRAY['K5-1-u6-C4']::text[],'빗댄 것과 대상의 비슷한 점을 시에 나오지 않는 엉뚱한 점에서 찾는다','시에서 어떻게 그렸나요'),
('K5-1-u6-X05','kor',5,'u6',ARRAY['K5-1-u6-C5']::text[],'비유는 시에만 쓰는 특별한 기술이라 노랫말이나 관용어 · 속담 같은 일상의 말에는 없다고 여긴다','일상의 말에도 있어요'),
('K5-1-u6-X06','kor',5,'u6',ARRAY['K5-1-u6-C6']::text[],'인상적인 부분을 누구에게나 같은 정답이 있는 것이나 글에서 가장 긴 부분으로 여긴다','마음이 움직인 곳'),
('K5-1-u6-X07','kor',5,'u6',ARRAY['K5-1-u6-C7']::text[],'이 단원의 공부를 시 한쪽뿐이거나 비유와 관계없는 공부로 여긴다','시 낭송 · 이야기 감상'),
('K5-1-u6-X08','kor',5,'u6',ARRAY['K5-1-u6-C8']::text[],'시에서 표현하는 대상과 빗댄 것을 서로 바꾸어 여기거나 시 속 낱말 아무것이나 대상으로 고른다','무엇을 무엇에 빗대었나요'),
('K5-1-u6-X09','kor',5,'u6',ARRAY['K5-1-u6-C9']::text[],'견주는 말이 들어간 표현을 은유법으로 여기거나 은유법은 같다고 견주는 방법이라고 여긴다','바로 그것이라고 말해요'),
('K5-1-u6-X10','kor',5,'u6',ARRAY['K5-1-u6-C10']::text[],'「……은 ……이다」 꼴의 표현을 직유법으로 여기거나 직유법에는 견주는 말이 드러나지 않는다고 여긴다','견주는 말이 보여요'),
('K5-1-u6-X11','kor',5,'u6',ARRAY['K5-1-u6-C11']::text[],'직유법에 쓰이는 말을 같이 · 처럼 · 듯이 셋뿐으로 여겨 「같은」 · 「만큼」을 알아보지 못하거나, 그러나 · 왜냐하면 같은 말을 견주는 말로 고른다','같은 · 만큼도 견주는 말'),
('K5-1-u6-X12','kor',5,'u6',ARRAY['K5-1-u6-C12']::text[],'비유는 아무것에나 빗대면 된다고 여기거나 두 대상의 비슷한 점을 살피지 않는다','닮은 점이 있어야 해요'),
('K5-1-u6-X13','kor',5,'u6',ARRAY['K5-1-u6-C13']::text[],'「……은 ……이다」 꼴이기만 하면 사실을 말한 문장도 모두 은유법이라고 여긴다','서로 다른 두 대상이 겹쳤나요'),
('K5-1-u6-X14','kor',5,'u6',ARRAY['K5-1-u6-C14']::text[],'빗댄 것이 없이 사실을 그대로 말한 문장도 비유로 여기거나 대상이 나오기만 하면 비유라고 여긴다','다른 것에 빗대었나요'),
('K5-1-u6-X15','kor',5,'u6',ARRAY['K5-1-u6-C15']::text[],'직유와 은유는 이름만 다를 뿐 느낌은 언제나 똑같다고 여기거나, 방법을 바꾸면 뜻까지 바뀐다고 여긴다','견주기와 겹치기'),
('K5-1-u6-X16','kor',5,'u6',ARRAY['K5-1-u6-C16']::text[],'은유법 · 직유법의 이름을 외우는 것이 시 공부의 목적이라고 여긴다','알아보고 감상하기'),
('K5-1-u6-X17','kor',5,'u6',ARRAY['K5-1-u6-C17']::text[],'「나는 아직 새벽」의 말하는 이가 이미 다 자랐거나 모든 것이 끝난 시기에 있다고 여긴다','새벽은 하루의 처음'),
('K5-1-u6-X18','kor',5,'u6',ARRAY['K5-1-u6-C18']::text[],'시의 비유적 표현을 글자 그대로 풀거나 표현과 뜻을 엉뚱하게 짝짓는다','무엇을 빗대었나요'),
('K5-1-u6-X19','kor',5,'u6',ARRAY['K5-1-u6-C19']::text[],'자라는 시기를 하루에 빗댄 까닭을 시간이 짧다거나 날씨와 관계있기 때문으로 여긴다','차례대로 오고 건너뛸 수 없어요'),
('K5-1-u6-X20','kor',5,'u6',ARRAY['K5-1-u6-C20']::text[],'말하는 이의 마음을 되풀이되는 말과 관계없이 짐작하거나 빨리 자라게 되어 신난다고 여긴다','「하지만」 뒤를 보아요'),
('K5-1-u6-X21','kor',5,'u6',ARRAY['K5-1-u6-C21']::text[],'시 낭송은 한 가지 방법뿐이라고 여기거나 시와 관계없는 방법을 낭송 방법으로 고른다','분위기 · 마음 · 몸짓 · 번갈아'),
('K5-1-u6-X22','kor',5,'u6',ARRAY['K5-1-u6-C22']::text[],'낭송을 잘하려면 최대한 빠르게, 가장 큰 목소리로 읽으면 된다고 여긴다','분위기 · 마음 · 리듬'),
('K5-1-u6-X23','kor',5,'u6',ARRAY['K5-1-u6-C23']::text[],'어디서 쉬든 시의 느낌은 똑같다고 여기거나 쉬지 않고 이어 읽어야 잘 읽는 것이라고 여긴다','쉬는 곳에 힘이 실려요'),
('K5-1-u6-X24','kor',5,'u6',ARRAY['K5-1-u6-C24']::text[],'시의 분위기와 관계없이 모든 시를 힘차게 외치거나 우스꽝스럽게 낭송한다','분위기에 맞추어요'),
('K5-1-u6-X25','kor',5,'u6',ARRAY['K5-1-u6-C25']::text[],'시는 한 번 읽으면 충분하다고 여기거나 낭송은 결과만 잘 나오면 된다고 여긴다','여러 번 · 과정'),
('K5-1-u6-X26','kor',5,'u6',ARRAY['K5-1-u6-C26']::text[],'시를 나와 관계없는 남의 이야기로만 읽거나 나를 빗댈 때 까닭은 없어도 된다고 여긴다','지금의 나는?'),
('K5-1-u6-X27','kor',5,'u6',ARRAY['K5-1-u6-C27']::text[],'시로 쓸 대상은 본 적 없는 거창하고 화려한 것이어야 한다고 여기거나 친구의 비밀처럼 쓰면 안 되는 것을 고른다','겪은 일에서 와요'),
('K5-1-u6-X28','kor',5,'u6',ARRAY['K5-1-u6-C28']::text[],'대상을 살필 때 겉모습 하나만 적고 관련한 경험이나 생각 · 느낌은 떠올리지 않아도 된다고 여긴다','특징 · 경험 · 느낌'),
('K5-1-u6-X29','kor',5,'u6',ARRAY['K5-1-u6-C29']::text[],'눈에 보이는 색이나 모양만 대상의 특징이라고 여겨 하는 일이나 태도는 살피지 않는다','사진으로 찍을 수 없는 것'),
('K5-1-u6-X30','kor',5,'u6',ARRAY['K5-1-u6-C30']::text[],'비유를 만들 때 대상의 특징을 살피기 전에 빗댈 것부터 정하거나 차례를 뒤섞는다','대상 → 특징 → 빗댈 것'),
('K5-1-u6-X31','kor',5,'u6',ARRAY['K5-1-u6-C31']::text[],'뜻이 어렵거나 낱말이 화려하면 좋은 비유라고 여기거나 빗댄 까닭을 말하지 못해도 괜찮다고 여긴다','비슷한 점 · 까닭 · 마음'),
('K5-1-u6-X32','kor',5,'u6',ARRAY['K5-1-u6-C32']::text[],'한 시에 비유를 많이 넣을수록 좋은 시가 된다고 여긴다','잘 드러나는 하나'),
('K5-1-u6-X33','kor',5,'u6',ARRAY['K5-1-u6-C33']::text[],'감상 쪽지를 「잘 썼어」처럼 점수만 매기는 말로 채우거나 어느 표현이 왜 좋았는지 쓰지 않는다','어느 표현이 왜'),
('K5-1-u6-X34','kor',5,'u6',ARRAY['K5-1-u6-C34']::text[],'같은 대상이면 누구나 같은 것에 빗대야 한다고 여기거나 다르게 빗댄 것을 틀렸다고 여긴다','그 사람의 눈'),
('K5-1-u6-X35','kor',5,'u6',ARRAY['K5-1-u6-C35']::text[],'라디오 소리가 거슬리지 않게 된 까닭을 소리가 작아졌거나 휴대 전화를 다시 켰기 때문으로 여긴다','정전이 난 밤의 일'),
('K5-1-u6-X36','kor',5,'u6',ARRAY['K5-1-u6-C36']::text[],'「건전지 한 통을 샀다」처럼 사실을 적은 문장을 비유적 표현으로 고르거나 견주는 말이 든 표현을 놓친다','다른 것에 빗대었나요'),
('K5-1-u6-X37','kor',5,'u6',ARRAY['K5-1-u6-C37']::text[],'비유적 표현이 만드는 느낌을 표현과 반대로 짐작하거나 엉뚱하게 짝짓는다','떠오르는 장면을 그려요'),
('K5-1-u6-X38','kor',5,'u6',ARRAY['K5-1-u6-C38']::text[],'이야기에서 비유를 쓰는 까닭을 길이를 줄이거나 정확한 숫자를 알려 주려는 것으로 여긴다','장면과 마음'),
('K5-1-u6-X39','kor',5,'u6',ARRAY['K5-1-u6-C39']::text[],'이야기를 읽을 때 비유적 표현을 골라내는 것이 목적이라고 여겨 줄거리와 인물의 마음을 놓친다','누가 무엇을 겪었나요'),
('K5-1-u6-X40','kor',5,'u6',ARRAY['K5-1-u6-C40']::text[],'인상적인 부분을 이야기에서 가장 중요한 장면이나 정해진 정답으로 여기거나 글자 수처럼 관계없는 것으로 고른다','내 마음이 움직인 장면'),
('K5-1-u6-X41','kor',5,'u6',ARRAY['K5-1-u6-C41']::text[],'인상적인 부분을 고른 까닭을 「그냥 좋아서」처럼 작품 내용과 이어지지 않게 말해도 된다고 여긴다','어느 대목 때문에?'),
('K5-1-u6-X42','kor',5,'u6',ARRAY['K5-1-u6-C42']::text[],'작품은 작품일 뿐이라 내 삶과 이어 생각할 필요가 없다고 여긴다','내 삶으로 이어요'),
('K5-1-u6-X43','kor',5,'u6',ARRAY['K5-1-u6-C43']::text[],'신화를 요즘 일어난 일을 그대로 적은 기록이나 평범한 사람의 하루를 그린 이야기로 여긴다','오래전부터 전해 온 이야기'),
('K5-1-u6-X44','kor',5,'u6',ARRAY['K5-1-u6-C44']::text[],'신화에서 일이 일어난 차례를 뒤섞거나 일이 일어난 까닭을 엉뚱하게 짐작한다','차례와 까닭'),
('K5-1-u6-X45','kor',5,'u6',ARRAY['K5-1-u6-C45']::text[],'도읍 · 태자 · 후환 · 단연의 뜻을 서로 헷갈린다','쓰인 문장을 다시 보아요'),
('K5-1-u6-X46','kor',5,'u6',ARRAY['K5-1-u6-C46']::text[],'신화는 옛이야기라 비유적 표현이 없다고 여기거나 사실을 적은 문장을 비유로 고른다','처럼이 든 표현'),
('K5-1-u6-X47','kor',5,'u6',ARRAY['K5-1-u6-C47']::text[],'신화의 특징을 모든 사건이 날짜까지 정확하다거나 평범한 사람의 하루를 그린다는 것으로 여긴다','비범한 탄생 · 시련 · 도움'),
('K5-1-u6-X48','kor',5,'u6',ARRAY['K5-1-u6-C48']::text[],'여러 신화의 닮은 점을 모두 같은 나라 이야기라거나 모두 알에서 태어난다는 것으로 여긴다','특별한 인물 · 놀라운 사건 · 시작'),
('K5-1-u6-X49','kor',5,'u6',ARRAY['K5-1-u6-C49']::text[],'같은 장면을 고르면 느낀 것도 같아야 한다고 여기거나 감상 나누기를 누구의 감상이 맞는지 가리는 일로 여긴다','한 장면 · 여러 해석'),
('K5-1-u6-X50','kor',5,'u6',ARRAY['K5-1-u6-C50']::text[],'책갈피를 만들 때 작품과 표현을 고르기 전에 꾸미기부터 하거나 차례를 뒤섞는다','작품 → 표현 → 앞뒷면 → 끈'),
('K5-1-u6-X51','kor',5,'u6',ARRAY['K5-1-u6-C51']::text[],'책갈피에 사실만 적은 문장을 담거나 장면이 떠오르지 않는 표현을 고른다','한 줄로 장면이 떠올라요'),
('K5-1-u6-X52','kor',5,'u6',ARRAY['K5-1-u6-C52']::text[],'책갈피 그림을 표현과 관계없는 그림으로 그리거나 표현을 글로 다시 설명하는 것이라고 여긴다','표현이 만든 장면'),
('K5-1-u6-X53','kor',5,'u6',ARRAY['K5-1-u6-C53']::text[],'작은 책갈피에 시 전체를 빽빽하게 옮겨 적거나 가져온 표현의 제목과 지은이를 적지 않아도 된다고 여긴다','한두 줄 · 출처'),
('K5-1-u6-X54','kor',5,'u6',ARRAY['K5-1-u6-C54']::text[],'책갈피를 소개할 때 걸린 시간이나 쓴 색연필의 개수처럼 표현과 관계없는 것을 말하거나 「그냥 예뻐서」로 끝낸다','고른 표현과 까닭'),
('K5-1-u6-X55','kor',5,'u6',ARRAY['K5-1-u6-C55']::text[],'비유는 시에만 쓰는 기술이라 여기거나 바로 말하지 않고 이야기로 빗대어 말하는 것은 쓸모없다고 여긴다','스스로 깨닫게 해요'),
('K5-1-u6-X56','kor',5,'u6',ARRAY['K5-1-u6-C56']::text[],'「조개와 황새」를 조개 잡는 방법이나 황새가 더 세다는 이야기로 글자 그대로만 읽는다','누가 무엇을 나타내나요'),
('K5-1-u6-X57','kor',5,'u6',ARRAY['K5-1-u6-C57']::text[],'잘 듣기를 가만히 앉아 있기만 하는 일로 여기거나 네 가지 방법을 헷갈린다','귀 기울이기 · 정리 · 질문 · 확인'),
('K5-1-u6-X58','kor',5,'u6',ARRAY['K5-1-u6-C58']::text[],'흘려듣기 · 골라 듣기 · 따지며 듣기 · 묻지 않기처럼 대화를 끊는 듣기를 괜찮다고 여긴다','대화가 이어지게')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g5_1_kor_u6_L01_basic#1','kor',5,1,'u6','L01','g5_1_kor_u6_L01_basic','lesson_basic','K5-1-u6-C1',1,'mc','auto','비유적 표현의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X01','K5-1-u6-X03']::text[],false,'{"seq":1,"concept":"K5-1-u6-C1","difficulty":1,"kind":"mc","stem":"비유적 표현의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"어떤 대상을 비슷한 점이 있는 다른 대상에 빗대어 표현하는 것","correct":true},{"t":"사실을 있는 그대로 자세히 적는 것","mis":"K5-1-u6-X01"},{"t":"어려운 낱말을 많이 쓰는 것","mis":"K5-1-u6-X01"},{"t":"글의 길이를 길게 늘이는 것","mis":"K5-1-u6-X03"}],"explanation":["있는 그대로 적는 것과 달라요.","어려운 낱말과 관계없어요.","비슷한 것에 빗대어 표현해요."]}'::jsonb),
('g5_1_kor_u6_L01_basic#2','kor',5,1,'u6','L01','g5_1_kor_u6_L01_basic','lesson_basic','K5-1-u6-C2',1,'mc','auto','소율이가 한 「얼굴이 홍당무가 됐어」는 무슨 뜻인가요?',ARRAY['K5-1-u6-X02']::text[],false,'{"seq":2,"concept":"K5-1-u6-C2","difficulty":1,"kind":"mc","stem":"소율이가 한 「얼굴이 홍당무가 됐어」는 무슨 뜻인가요?","options":[{"t":"얼굴이 홍당무처럼 빨개졌다","correct":true},{"t":"얼굴이 정말 홍당무로 바뀌었다","mis":"K5-1-u6-X02"},{"t":"소율이가 홍당무를 먹었다","mis":"K5-1-u6-X02"},{"t":"소율이가 거짓말을 했다","mis":"K5-1-u6-X02"}],"explanation":["정말 바뀐 것이 아니에요.","먹은 이야기가 아니에요.","빨개진 모습을 견주어 말했어요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"아까 발표할 때 얼굴이 홍당무가 됐어."},{"who":"유담","text":"나는 운동장을 한 바퀴 돌았더니 땀이 폭포처럼 흘렀어."}]}}'::jsonb),
('g5_1_kor_u6_L01_basic#3','kor',5,1,'u6','L01','g5_1_kor_u6_L01_basic','lesson_basic','K5-1-u6-C4',1,'mc','auto','시 「지우개」에서 지우개와 눈사람의 비슷한 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X04']::text[],false,'{"seq":3,"concept":"K5-1-u6-C4","difficulty":1,"kind":"mc","stem":"시 「지우개」에서 지우개와 눈사람의 비슷한 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"하얗고 지날수록 점점 작아진다","correct":true},{"t":"둘 다 차갑다","mis":"K5-1-u6-X04"},{"t":"둘 다 겨울에만 볼 수 있다","mis":"K5-1-u6-X04"},{"t":"둘 다 공책 위에서 산다","mis":"K5-1-u6-X04"}],"explanation":["시에 차갑다는 말은 없어요.","계절 이야기가 아니에요.","시에서 지우개가 어떻게 변하는지 보아요."],"asset":{"type":"passage","lines":["공책 위를 지나간 곳마다 하얀 길이 생긴다","지우개는 작은 눈사람","지날수록 조금씩 작아진다","내 실수를 다 데리고","제 몸을 덜어 가며 걸어간다","다 닳은 지우개를 손에 쥐면 괜히 미안해진다"],"title":"시 「지우개」"}}'::jsonb),
('g5_1_kor_u6_L01_basic#4','kor',5,1,'u6','L01','g5_1_kor_u6_L01_basic','lesson_basic','K5-1-u6-C5',1,'ox','auto','비유적 표현은 시에만 쓰이는 특별한 말이에요.',ARRAY['K5-1-u6-X05']::text[],false,'{"seq":4,"concept":"K5-1-u6-C5","difficulty":1,"kind":"ox","stem":"비유적 표현은 시에만 쓰이는 특별한 말이에요.","answer":"X","reason_options":[{"t":"노랫말이나 관용어, 속담 같은 일상의 말에도 들어 있기 때문에","correct":true},{"t":"시를 쓰는 사람만 빗대어 말할 수 있기 때문에","mis":"K5-1-u6-X05"}],"mis":"K5-1-u6-X05","explanation":["시 밖에도 비유가 있어요.","「발이 넓다」를 떠올려요.","일상의 말에도 비유가 들어 있어요."]}'::jsonb),
('g5_1_kor_u6_L01_basic#5','kor',5,1,'u6','L01','g5_1_kor_u6_L01_basic','lesson_basic','K5-1-u6-C3',2,'mc','auto','빗대어 표현하면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X03','K5-1-u6-X01']::text[],false,'{"seq":5,"concept":"K5-1-u6-C3","difficulty":2,"kind":"mc","stem":"빗대어 표현하면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"장면을 더 생생하게 떠올리게 해 준다","correct":true},{"t":"글의 길이를 늘릴 수 있다","mis":"K5-1-u6-X03"},{"t":"어려운 낱말을 쓸 수 있다","mis":"K5-1-u6-X03"},{"t":"사실을 정확한 숫자로 알려 준다","mis":"K5-1-u6-X01"}],"explanation":["길이를 늘리려는 것이 아니에요.","어려운 말과 관계없어요.","장면이 생생하게 떠올라요."]}'::jsonb),
('g5_1_kor_u6_L01_basic#6','kor',5,1,'u6','L01','g5_1_kor_u6_L01_basic','lesson_basic','K5-1-u6-C6',2,'mc','auto','인상적인 부분으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X06']::text[],false,'{"seq":6,"concept":"K5-1-u6-C6","difficulty":2,"kind":"mc","stem":"인상적인 부분으로 알맞은 것은 어느 것인가요?","options":[{"t":"작품을 읽고 유난히 마음에 남는 부분","correct":true},{"t":"글에서 가장 긴 부분","mis":"K5-1-u6-X06"},{"t":"누구나 똑같이 골라야 하는 정답","mis":"K5-1-u6-X06"},{"t":"작품의 맨 처음 문장","mis":"K5-1-u6-X06"}],"explanation":["길이와 관계없어요.","정답이 정해져 있지 않아요.","마음이 움직인 곳이에요."]}'::jsonb),
('g5_1_kor_u6_L01_basic#7','kor',5,1,'u6','L01','g5_1_kor_u6_L01_basic','lesson_basic','K5-1-u6-C7',2,'mc','auto','이 단원에서 배우는 두 갈래로 알맞게 짝지은 것은 어느 것인가요?',ARRAY['K5-1-u6-X07']::text[],false,'{"seq":7,"concept":"K5-1-u6-C7","difficulty":2,"kind":"mc","stem":"이 단원에서 배우는 두 갈래로 알맞게 짝지은 것은 어느 것인가요?","options":[{"t":"비유적 표현을 알고 시 낭송하기 · 인상적인 부분을 중심으로 이야기 감상하기","correct":true},{"t":"토의 절차 익히기 · 의견 조정하기","mis":"K5-1-u6-X07"},{"t":"설명하는 글 쓰기 · 내용 요약하기","mis":"K5-1-u6-X07"},{"t":"시 낭송하기만 하고 이야기는 읽지 않기","mis":"K5-1-u6-X07"}],"explanation":["토의는 앞 단원이에요.","설명하는 글도 앞 단원이에요.","시 낭송과 이야기 감상 두 갈래예요."]}'::jsonb),
('g5_1_kor_u6_L01_basic#8','kor',5,1,'u6','L01','g5_1_kor_u6_L01_basic','lesson_basic','K5-1-u6-C4',2,'blank','auto','빈칸에 알맞은 말은 어느 것인가요? 「지우개를 눈사람에 빗댄 것은 둘 사이에 (　　)이 있기 때문이다.」',ARRAY['K5-1-u6-X04']::text[],false,'{"seq":8,"concept":"K5-1-u6-C4","difficulty":2,"kind":"blank","stem":"빈칸에 알맞은 말은 어느 것인가요? 「지우개를 눈사람에 빗댄 것은 둘 사이에 (　　)이 있기 때문이다.」","options":[{"t":"비슷한 점","correct":true},{"t":"다른 점","mis":"K5-1-u6-X04"},{"t":"같은 이름","mis":"K5-1-u6-X04"},{"t":"같은 값","mis":"K5-1-u6-X04"}],"explanation":["다른 점으로는 빗댈 수 없어요.","이름과 관계없어요.","닮은 점이 있어야 빗대요."]}'::jsonb),
('g5_1_kor_u6_L01_basic#9','kor',5,1,'u6','L01','g5_1_kor_u6_L01_basic','lesson_basic','K5-1-u6-C5',2,'match','auto','일상 속 말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u6-C5","difficulty":2,"kind":"match","stem":"일상 속 말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"발이 넓다","r":"아는 사람이 많다"},{"l":"티끌 모아 태산","r":"작은 것도 모이면 크게 된다"},{"l":"땀이 폭포처럼 흘렀다","r":"땀이 아주 많이 흘렀다"}],"mis":"K5-1-u6-X05","explanation":["발 크기 이야기가 아니에요.","티끌이 모여 산이 돼요.","폭포처럼 쏟아지는 땀이에요."]}'::jsonb),
('g5_1_kor_u6_L01_basic#10','kor',5,1,'u6','L01','g5_1_kor_u6_L01_basic','lesson_basic','K5-1-u6-C1',3,'mc','auto','다음 가운데 비유적 표현이 쓰인 문장은 어느 것인가요?',ARRAY['K5-1-u6-X14']::text[],false,'{"seq":10,"concept":"K5-1-u6-C1","difficulty":3,"kind":"mc","stem":"다음 가운데 비유적 표현이 쓰인 문장은 어느 것인가요?","options":[{"t":"내 동생 웃음소리는 작은 종소리 같다","correct":true},{"t":"내 동생은 웃음소리가 크다","mis":"K5-1-u6-X14"},{"t":"내 동생은 오늘 아침에 웃었다","mis":"K5-1-u6-X14"},{"t":"내 동생 이름은 새봄이다","mis":"K5-1-u6-X14"}],"explanation":["있는 그대로 말했어요.","있었던 일을 그대로 말했어요.","웃음소리를 종소리에 빗대었어요."]}'::jsonb),
('g5_1_kor_u6_L01_challenge#1','kor',5,1,'u6','L01','g5_1_kor_u6_L01_challenge','lesson_challenge','K5-1-u6-C2',2,'ox','auto','유담이의 「땀이 폭포처럼 흘렀어」는 사실이 아니므로 거짓말이에요.',ARRAY['K5-1-u6-X02']::text[],false,'{"seq":1,"concept":"K5-1-u6-C2","difficulty":2,"kind":"ox","stem":"유담이의 「땀이 폭포처럼 흘렀어」는 사실이 아니므로 거짓말이에요.","answer":"X","reason_options":[{"t":"실제로 그렇다는 말이 아니라 모습이 잘 떠오르게 견주어 말한 것이기 때문에","correct":true},{"t":"사실과 다른 말은 모두 거짓말이기 때문에","mis":"K5-1-u6-X02"}],"mis":"K5-1-u6-X02","explanation":["땀이 정말 폭포가 된 건 아니에요.","속이려는 말이 아니에요.","견주어 말한 비유예요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"아까 발표할 때 얼굴이 홍당무가 됐어."},{"who":"유담","text":"나는 운동장을 한 바퀴 돌았더니 땀이 폭포처럼 흘렀어."}]}}'::jsonb),
('g5_1_kor_u6_L01_challenge#2','kor',5,1,'u6','L01','g5_1_kor_u6_L01_challenge','lesson_challenge','K5-1-u6-C6',2,'mc','auto','인상적인 부분에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X06','K5-1-u6-X41']::text[],false,'{"seq":2,"concept":"K5-1-u6-C6","difficulty":2,"kind":"mc","stem":"인상적인 부분에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"사람마다 고르는 부분과 그 까닭이 다를 수 있다","correct":true},{"t":"모든 사람이 같은 부분을 골라야 한다","mis":"K5-1-u6-X06"},{"t":"작품에서 가장 긴 문단이 인상적인 부분이다","mis":"K5-1-u6-X06"},{"t":"까닭이 없어도 정답만 맞히면 된다","mis":"K5-1-u6-X41"}],"explanation":["같을 필요가 없어요.","길이와 관계없어요.","사람마다 다르고 까닭도 저마다 달라요."]}'::jsonb),
('g5_1_kor_u6_L01_challenge#3','kor',5,1,'u6','L01','g5_1_kor_u6_L01_challenge','lesson_challenge','K5-1-u6-C3',3,'mc','auto','시 「지우개」의 「제 몸을 덜어 가며 걸어간다」에 담긴 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X04']::text[],false,'{"seq":3,"concept":"K5-1-u6-C3","difficulty":3,"kind":"mc","stem":"시 「지우개」의 「제 몸을 덜어 가며 걸어간다」에 담긴 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"제 몸을 덜어 남을 돕는 지우개에 대한 고마움과 미안함","correct":true},{"t":"지우개가 빨리 없어져서 기쁜 마음","mis":"K5-1-u6-X04"},{"t":"지우개를 새로 사고 싶은 마음","mis":"K5-1-u6-X04"},{"t":"공책이 더러워져서 화난 마음","mis":"K5-1-u6-X04"}],"explanation":["기쁜 마음이 아니에요.","새로 사자는 시가 아니에요.","마지막 행의 「미안해진다」를 보아요."],"asset":{"type":"passage","lines":["공책 위를 지나간 곳마다 하얀 길이 생긴다","지우개는 작은 눈사람","지날수록 조금씩 작아진다","내 실수를 다 데리고","제 몸을 덜어 가며 걸어간다","다 닳은 지우개를 손에 쥐면 괜히 미안해진다"],"title":"시 「지우개」"}}'::jsonb),
('g5_1_kor_u6_L01_challenge#4','kor',5,1,'u6','L01','g5_1_kor_u6_L01_challenge','lesson_challenge','K5-1-u6-C1',3,'mc','auto','「지우개는 작은 눈사람」에서 빗대는 대상과 빗댄 것을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K5-1-u6-X08']::text[],false,'{"seq":4,"concept":"K5-1-u6-C1","difficulty":3,"kind":"mc","stem":"「지우개는 작은 눈사람」에서 빗대는 대상과 빗댄 것을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"빗대는 대상 — 지우개 / 빗댄 것 — 눈사람","correct":true},{"t":"빗대는 대상 — 눈사람 / 빗댄 것 — 지우개","mis":"K5-1-u6-X08"},{"t":"빗대는 대상 — 공책 / 빗댄 것 — 지우개","mis":"K5-1-u6-X08"},{"t":"빗대는 대상 — 실수 / 빗댄 것 — 공책","mis":"K5-1-u6-X08"}],"explanation":["둘이 뒤바뀌었어요.","공책은 대상이 아니에요.","지우개를 눈사람에 빗대었어요."],"asset":{"type":"passage","lines":["공책 위를 지나간 곳마다 하얀 길이 생긴다","지우개는 작은 눈사람","지날수록 조금씩 작아진다","내 실수를 다 데리고","제 몸을 덜어 가며 걸어간다","다 닳은 지우개를 손에 쥐면 괜히 미안해진다"],"title":"시 「지우개」"}}'::jsonb),
('g5_1_kor_u6_L01_challenge#5','kor',5,1,'u6','L01','g5_1_kor_u6_L01_challenge','lesson_challenge','K5-1-u6-C5',3,'error','auto','비유에 대해 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u6-X05']::text[],false,'{"seq":5,"concept":"K5-1-u6-C5","difficulty":3,"kind":"error","stem":"비유에 대해 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「비유는 시를 쓸 때만 쓰는 말이야.」","correct":true,"mis_target":"K5-1-u6-X05"},{"t":"「속담에도 빗대어 말한 것이 있어.」","mis":"K5-1-u6-X05"},{"t":"「노랫말에도 비유가 자주 나와.」","mis":"K5-1-u6-X05"}],"explanation":["속담에도 비유가 있어요.","노랫말에도 있어요.","비유는 일상의 말에도 들어 있어요."]}'::jsonb),
('g5_1_kor_u6_L01_challenge#6','kor',5,1,'u6','L01','g5_1_kor_u6_L01_challenge','lesson_challenge','K5-1-u6-C3',3,'mc','auto','「친구가 반가웠다」를 「친구 얼굴이 봄 햇살 같았다」로 바꾸면 무엇이 달라지나요?',ARRAY['K5-1-u6-X03','K5-1-u6-X02','K5-1-u6-X01']::text[],false,'{"seq":6,"concept":"K5-1-u6-C3","difficulty":3,"kind":"mc","stem":"「친구가 반가웠다」를 「친구 얼굴이 봄 햇살 같았다」로 바꾸면 무엇이 달라지나요?","options":[{"t":"반가운 마음이 장면처럼 생생하게 전해진다","correct":true},{"t":"글이 짧아져 읽기 쉬워진다","mis":"K5-1-u6-X03"},{"t":"친구가 정말 햇살이 되었다는 뜻이 된다","mis":"K5-1-u6-X02"},{"t":"사실을 더 정확하게 알려 준다","mis":"K5-1-u6-X01"}],"explanation":["짧아지지 않았어요.","정말 햇살이 된 게 아니에요.","마음이 생생하게 전해져요."]}'::jsonb),
('g5_1_kor_u6_L01_challenge#7','kor',5,1,'u6','L01','g5_1_kor_u6_L01_challenge','lesson_challenge','K5-1-u6-C7',3,'mc','auto','이 단원의 비유적 표현과 인상적인 부분이 이어지는 모습으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X07','K5-1-u6-X39']::text[],false,'{"seq":7,"concept":"K5-1-u6-C7","difficulty":3,"kind":"mc","stem":"이 단원의 비유적 표현과 인상적인 부분이 이어지는 모습으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"작품 속 비유가 만든 장면이 마음에 남아 인상적인 부분이 될 수 있다","correct":true},{"t":"비유와 인상적인 부분은 서로 관계없다","mis":"K5-1-u6-X07"},{"t":"인상적인 부분에는 비유가 없어야 한다","mis":"K5-1-u6-X07"},{"t":"비유를 많이 찾을수록 인상적인 부분이 정해진다","mis":"K5-1-u6-X39"}],"explanation":["둘은 이어져요.","비유가 있어도 돼요.","비유가 만든 장면이 마음에 남을 수 있어요."]}'::jsonb),
('g5_1_kor_u6_L01_challenge#8','kor',5,1,'u6','L01','g5_1_kor_u6_L01_challenge','lesson_challenge','K5-1-u6-C1',4,'essay','teacher','가까이 있는 물건 하나를 골라 다른 것에 빗대어 한 문장으로 쓰고, 두 대상의 비슷한 점을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u6-C1","difficulty":4,"kind":"essay","stem":"가까이 있는 물건 하나를 골라 다른 것에 빗대어 한 문장으로 쓰고, 두 대상의 비슷한 점을 쓰세요.","answer_guide":{"answer":"예: 우리 반 시계는 쉬지 않는 달리기 선수다. 시곗바늘은 멈추지 않고 계속 돌아가고, 달리기 선수도 쉬지 않고 달린다는 점이 비슷하다.","scoring_points":["물건 하나를 골라 빗대어 썼는가","두 대상의 비슷한 점을 썼는가","실제로 그렇다는 말이 아니라 견주어 말한 것인가"]},"explanation":["무엇을 골랐나요?","무엇에 빗대었나요?","어떤 점이 닮았나요?"]}'::jsonb),
('g5_1_kor_u6_L01_challenge#9','kor',5,1,'u6','L01','g5_1_kor_u6_L01_challenge','lesson_challenge','K5-1-u6-C3',4,'essay','teacher','소율이와 유담이의 말을 비유 없이 바꾸어 쓰고, 처음 말과 무엇이 다른지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u6-C3","difficulty":4,"kind":"essay","stem":"소율이와 유담이의 말을 비유 없이 바꾸어 쓰고, 처음 말과 무엇이 다른지 쓰세요.","answer_guide":{"answer":"예: 「발표할 때 얼굴이 빨개졌어.」, 「땀이 아주 많이 흘렀어.」로 바꿀 수 있다. 처음 말은 얼굴이 얼마나 빨갰는지, 땀이 얼마나 많았는지 모습이 눈앞에 떠올라 더 생생하고 느낌이 잘 전해진다.","scoring_points":["두 말을 비유 없이 바꾸어 썼는가","처음 말과 견주었는가","생생함이나 느낌의 차이를 썼는가"]},"explanation":["비유를 빼면 어떻게 되나요?","무엇이 사라지나요?","생생함을 견주어요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"아까 발표할 때 얼굴이 홍당무가 됐어."},{"who":"유담","text":"나는 운동장을 한 바퀴 돌았더니 땀이 폭포처럼 흘렀어."}]}}'::jsonb),
('g5_1_kor_u6_L01_challenge#10','kor',5,1,'u6','L01','g5_1_kor_u6_L01_challenge','lesson_challenge','K5-1-u6-C6',4,'essay','teacher','최근에 읽은 책이나 본 영상에서 마음이 움직인 장면을 하나 떠올려 쓰고, 왜 그 장면이 마음에 남았는지 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u6-C6","difficulty":4,"kind":"essay","stem":"최근에 읽은 책이나 본 영상에서 마음이 움직인 장면을 하나 떠올려 쓰고, 왜 그 장면이 마음에 남았는지 까닭을 쓰세요.","answer_guide":{"answer":"예: 동화에서 주인공이 잃어버린 강아지를 다시 찾는 장면이 마음에 남았다. 나도 고양이를 잃어버렸다가 찾은 적이 있어서 주인공의 기쁜 마음을 잘 알 것 같았다.","scoring_points":["장면을 하나 썼는가","마음에 남은 까닭을 썼는가","자기 경험이나 생각과 이어 썼는가"]},"explanation":["어떤 장면이었나요?","왜 마음이 움직였나요?","내 경험과 이어 보아요."]}'::jsonb),
('g5_1_kor_u6_L02_basic#1','kor',5,1,'u6','L02','g5_1_kor_u6_L02_basic','lesson_basic','K5-1-u6-C8',1,'mc','auto','시 「내 마음은 유리병」에서 표현하는 대상은 어느 것인가요?',ARRAY['K5-1-u6-X08']::text[],false,'{"seq":1,"concept":"K5-1-u6-C8","difficulty":1,"kind":"mc","stem":"시 「내 마음은 유리병」에서 표현하는 대상은 어느 것인가요?","options":[{"t":"내 마음","correct":true},{"t":"유리병","mis":"K5-1-u6-X08"},{"t":"흙탕물","mis":"K5-1-u6-X08"},{"t":"맑은 물","mis":"K5-1-u6-X08"}],"explanation":["유리병은 빗댄 것이에요.","흙탕물은 시 속 장면이에요.","첫 행을 다시 읽어요."],"asset":{"type":"passage","lines":["내 마음은 유리병","속이 다 비쳐 보인다","기분 좋은 날에는 맑은 물이 찰랑이고","서운한 날에는 흙탕물이 가라앉지 못한다","누가 툭 건드리면 소리부터 먼저 난다","그래서 나는 잠들기 전에 병을 조용히 세워 둔다"],"title":"시 「내 마음은 유리병」"}}'::jsonb),
('g5_1_kor_u6_L02_basic#2','kor',5,1,'u6','L02','g5_1_kor_u6_L02_basic','lesson_basic','K5-1-u6-C9',1,'mc','auto','은유법으로 표현한 것은 어느 것인가요?',ARRAY['K5-1-u6-X09','K5-1-u6-X14']::text[],false,'{"seq":2,"concept":"K5-1-u6-C9","difficulty":1,"kind":"mc","stem":"은유법으로 표현한 것은 어느 것인가요?","options":[{"t":"교실은 작은 숲이다","correct":true},{"t":"교실이 숲처럼 시끄럽다","mis":"K5-1-u6-X09"},{"t":"교실에 나무 화분이 있다","mis":"K5-1-u6-X14"},{"t":"교실 창문이 활짝 열렸다","mis":"K5-1-u6-X14"}],"explanation":["「처럼」이 있으면 직유예요.","그냥 사실이에요.","바로 숲이라고 말했어요."]}'::jsonb),
('g5_1_kor_u6_L02_basic#3','kor',5,1,'u6','L02','g5_1_kor_u6_L02_basic','lesson_basic','K5-1-u6-C10',1,'mc','auto','직유법으로 표현한 것은 어느 것인가요?',ARRAY['K5-1-u6-X10','K5-1-u6-X14']::text[],false,'{"seq":3,"concept":"K5-1-u6-C10","difficulty":1,"kind":"mc","stem":"직유법으로 표현한 것은 어느 것인가요?","options":[{"t":"우산처럼 옆으로 기울어 주는 친구","correct":true},{"t":"내 마음은 유리병","mis":"K5-1-u6-X10"},{"t":"비 오는 날 우산을 썼다","mis":"K5-1-u6-X14"},{"t":"계단을 한 칸씩 올라갔다","mis":"K5-1-u6-X14"}],"explanation":["견주는 말이 없으면 은유예요.","있었던 일 그대로예요.","「처럼」으로 견주었어요."]}'::jsonb),
