('g5_1_kor_u6_L08_challenge#6','kor',5,1,'u6','L08','g5_1_kor_u6_L08_challenge','lesson_challenge','K5-1-u6-C42',3,'mc','auto','이 이야기를 내 삶과 이어 감상한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X42','K5-1-u6-X39']::text[],false,'{"seq":6,"concept":"K5-1-u6-C42","difficulty":3,"kind":"mc","stem":"이 이야기를 내 삶과 이어 감상한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"바쁘다는 까닭으로 할아버지 이야기를 제대로 들어 드리지 못한 일이 떠올랐다","correct":true},{"t":"라디오는 건전지가 있어야 움직인다","mis":"K5-1-u6-X42"},{"t":"이야기에 비유가 네 개 나온다","mis":"K5-1-u6-X39"},{"t":"여름 방학은 나흘보다 길다","mis":"K5-1-u6-X42"}],"explanation":["내 삶과 이은 게 아니에요.","비유 세기는 감상이 아니에요.","내 경험과 이어 보아요."]}'::jsonb),
('g5_1_kor_u6_L08_challenge#7','kor',5,1,'u6','L08','g5_1_kor_u6_L08_challenge','lesson_challenge','K5-1-u6-C38',3,'mc','auto','「라디오 소리가 마당까지 나와 있었다」에 담긴 느낌으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X37','K5-1-u6-X35','K5-1-u6-X36']::text[],false,'{"seq":7,"concept":"K5-1-u6-C38","difficulty":3,"kind":"mc","stem":"「라디오 소리가 마당까지 나와 있었다」에 담긴 느낌으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"할머니와 라디오가 재하를 배웅하는 듯한 따뜻한 마음","correct":true},{"t":"라디오 소리가 너무 커서 시끄럽다는 불만","mis":"K5-1-u6-X37"},{"t":"라디오가 고장 났다는 걱정","mis":"K5-1-u6-X35"},{"t":"마당에 라디오를 내놓았다는 사실","mis":"K5-1-u6-X36"}],"explanation":["불만이 아니에요.","고장 난 게 아니에요.","배웅하는 마음이 느껴져요."],"asset":{"type":"passage","lines":["다음 날 불이 들어오고 라디오도 다시 켜졌다.","그런데 그 소리가 전날처럼 거슬리지 않았다.","돌아가는 날 아침, 재하는 건전지 한 통을 샀다.","라디오의 낡은 건전지를 새것으로 갈아 끼웠다.","「말동무 목소리가 커졌네.」 할머니가 웃었다.","버스에 오르며 돌아보니 라디오 소리가 마당까지 나와 있었다."],"title":"이야기 「할머니의 라디오」 ③"}}'::jsonb),
('g5_1_kor_u6_L08_challenge#8','kor',5,1,'u6','L08','g5_1_kor_u6_L08_challenge','lesson_challenge','K5-1-u6-C40',4,'essay','teacher','「할머니의 라디오」에서 가장 마음이 움직인 장면을 하나 고르고, 그 장면이 왜 마음에 남았는지 이야기 속 대목을 근거로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u6-C40","difficulty":4,"kind":"essay","stem":"「할머니의 라디오」에서 가장 마음이 움직인 장면을 하나 고르고, 그 장면이 왜 마음에 남았는지 이야기 속 대목을 근거로 쓰세요.","answer_guide":{"answer":"예: 정전이 난 밤 할머니가 재하를 부른 장면이 마음에 남았다. 어둠이 두꺼운 담요처럼 무서웠는데 할머니 목소리가 낮은 강물처럼 흘러와 재하가 다가가 앉는 모습에서 마음이 놓였다.","scoring_points":["장면을 하나 골랐는가","이야기 속 대목을 근거로 들었는가","마음이 움직인 까닭을 썼는가"]},"explanation":["어느 장면인가요?","어느 대목 때문인가요?","내 마음을 써요."]}'::jsonb),
('g5_1_kor_u6_L08_challenge#9','kor',5,1,'u6','L08','g5_1_kor_u6_L08_challenge','lesson_challenge','K5-1-u6-C38',4,'essay','teacher','이야기 속 비유적 표현 하나를 골라 비유 없이 바꾸어 쓰고, 두 문장이 주는 느낌을 견주어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u6-C38","difficulty":4,"kind":"essay","stem":"이야기 속 비유적 표현 하나를 골라 비유 없이 바꾸어 쓰고, 두 문장이 주는 느낌을 견주어 쓰세요.","answer_guide":{"answer":"예: 「그 소리는 낮은 강물처럼 방바닥을 타고 흘러왔다」를 「할머니가 낮은 목소리로 말했다」로 바꿀 수 있다. 바꾼 문장은 무엇이 일어났는지만 알려 주지만, 처음 문장은 목소리가 잔잔하게 퍼져 재하의 무서운 마음을 달래 주는 느낌까지 전해 준다.","scoring_points":["비유적 표현을 골랐는가","비유 없이 바꾸어 썼는가","두 문장의 느낌을 견주었는가"]},"explanation":["어떤 표현을 고를까요?","비유를 빼면?","무엇이 사라지나요?"]}'::jsonb),
('g5_1_kor_u6_L08_challenge#10','kor',5,1,'u6','L08','g5_1_kor_u6_L08_challenge','lesson_challenge','K5-1-u6-C39',4,'essay','teacher','재하의 마음이 처음과 끝에 어떻게 달라졌는지 쓰고, 그렇게 달라진 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u6-C39","difficulty":4,"kind":"essay","stem":"재하의 마음이 처음과 끝에 어떻게 달라졌는지 쓰고, 그렇게 달라진 까닭을 쓰세요.","answer_guide":{"answer":"예: 처음에 재하는 라디오 소리가 거슬려 휴대 전화만 붙들었다. 끝에는 건전지를 갈아 끼울 만큼 라디오와 할머니를 소중히 여기게 되었다. 정전이 난 밤 할머니의 이야기를 오래 들으며 할머니에게 라디오가 왜 말동무인지 알게 되었기 때문이다.","scoring_points":["처음의 마음을 썼는가","끝의 마음을 썼는가","달라진 까닭을 썼는가"]},"explanation":["처음엔 어땠나요?","끝엔 어땠나요?","무슨 일이 있었나요?"]}'::jsonb),
('g5_1_kor_u6_L10_basic#1','kor',5,1,'u6','L10','g5_1_kor_u6_L10_basic','lesson_basic','K5-1-u6-C43',1,'mc','auto','신화에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X43']::text[],false,'{"seq":1,"concept":"K5-1-u6-C43","difficulty":1,"kind":"mc","stem":"신화에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"아주 오래전부터 입에서 입으로 전해 온 이야기","correct":true},{"t":"요즘 일어난 일을 그대로 적은 기록","mis":"K5-1-u6-X43"},{"t":"평범한 사람의 하루를 그린 일기","mis":"K5-1-u6-X43"},{"t":"과학 실험의 결과를 적은 글","mis":"K5-1-u6-X43"}],"explanation":["요즘 일이 아니에요.","평범한 하루가 아니에요.","오래전부터 전해 왔어요."]}'::jsonb),
('g5_1_kor_u6_L10_basic#2','kor',5,1,'u6','L10','g5_1_kor_u6_L10_basic','lesson_basic','K5-1-u6-C44',1,'mc','auto','사람들이 아이를 주몽이라 부른 까닭은 어느 것인가요?',ARRAY['K5-1-u6-X44']::text[],false,'{"seq":2,"concept":"K5-1-u6-C44","difficulty":1,"kind":"mc","stem":"사람들이 아이를 주몽이라 부른 까닭은 어느 것인가요?","options":[{"t":"활을 아주 잘 쏘아서","correct":true},{"t":"알에서 태어나서","mis":"K5-1-u6-X44"},{"t":"말을 잘 먹여서","mis":"K5-1-u6-X44"},{"t":"강을 건너서","mis":"K5-1-u6-X44"}],"explanation":["이름의 까닭이 아니에요.","말 이야기는 뒤에 나와요.","활 잘 쏘는 사람이라는 뜻이에요."],"asset":{"type":"passage","lines":["왕이 알을 버리게 했지만 짐승들은 알을 밟지 않고 피해 다녔다.","새들은 날아와 깃털로 알을 덮어 주었다.","무엇으로도 깨지지 않던 알에서 마침내 아기가 태어났다.","아이는 일곱 살에 스스로 활을 만들어 쏘았다.","백 번을 쏘면 백 번을 맞혀 사람들은 아이를 주몽이라 불렀다."],"title":"신화 「알에서 태어난 아이」 ②"}}'::jsonb),
('g5_1_kor_u6_L10_basic#3','kor',5,1,'u6','L10','g5_1_kor_u6_L10_basic','lesson_basic','K5-1-u6-C45',1,'match','auto','신화 속 낱말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K5-1-u6-C45","difficulty":1,"kind":"match","stem":"신화 속 낱말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"도읍","r":"한 나라의 중앙 정부가 있는 곳"},{"l":"태자","r":"임금의 뒤를 이을 아들"},{"l":"후환","r":"뒷날 생기는 걱정과 근심"}],"mis":"K5-1-u6-X45","explanation":["주몽은 졸본주를 도읍으로 삼았어요.","대소는 태자예요.","후환은 뒷날의 걱정이에요."]}'::jsonb),
('g5_1_kor_u6_L10_basic#4','kor',5,1,'u6','L10','g5_1_kor_u6_L10_basic','lesson_basic','K5-1-u6-C46',1,'ox','auto','신화는 옛이야기라서 비유적 표현이 쓰이지 않아요.',ARRAY['K5-1-u6-X46']::text[],false,'{"seq":4,"concept":"K5-1-u6-C46","difficulty":1,"kind":"ox","stem":"신화는 옛이야기라서 비유적 표현이 쓰이지 않아요.","answer":"X","reason_options":[{"t":"「갈대처럼 여윈 말」처럼 신화에도 비유적 표현이 쓰이기 때문에","correct":true},{"t":"비유는 요즘 쓴 시에만 나오기 때문에","mis":"K5-1-u6-X46"}],"mis":"K5-1-u6-X46","explanation":["신화에도 비유가 있어요.","「처럼」을 찾아보아요.","장면이 또렷해져요."]}'::jsonb),
('g5_1_kor_u6_L10_basic#5','kor',5,1,'u6','L10','g5_1_kor_u6_L10_basic','lesson_basic','K5-1-u6-C46',2,'mc','auto','신화 「알에서 태어난 아이」 ①에 쓰인 비유적 표현은 어느 것인가요?',ARRAY['K5-1-u6-X46']::text[],false,'{"seq":5,"concept":"K5-1-u6-C46","difficulty":2,"kind":"mc","stem":"신화 「알에서 태어난 아이」 ①에 쓰인 비유적 표현은 어느 것인가요?","options":[{"t":"그 빛은 그림자처럼 유화를 따라다녔다","correct":true},{"t":"얼마 뒤 유화는 커다란 알 하나를 낳았다","mis":"K5-1-u6-X46"},{"t":"왕은 유화를 햇빛이 들지 않는 방에 두었다","mis":"K5-1-u6-X46"},{"t":"금와왕이 못가에서 유화를 만났다","mis":"K5-1-u6-X46"}],"explanation":["있었던 일 그대로예요.","빗댄 것이 없어요.","빛을 그림자에 견주었어요."],"asset":{"type":"passage","lines":["동부여의 금와왕이 못가에서 유화라는 여인을 만났다.","유화는 물의 신 하백의 딸로, 아버지의 노여움을 사 쫓겨난 처지였다.","왕은 유화를 햇빛이 들지 않는 방에 두었다.","그런데 햇빛 한 줄기가 들어와 유화를 비추었다.","그 빛은 그림자처럼 유화를 따라다녔다.","얼마 뒤 유화는 커다란 알 하나를 낳았다."],"title":"신화 「알에서 태어난 아이」 ①"}}'::jsonb),
('g5_1_kor_u6_L10_basic#6','kor',5,1,'u6','L10','g5_1_kor_u6_L10_basic','lesson_basic','K5-1-u6-C47',2,'mc','auto','신화에서 자주 나타나는 특징은 어느 것인가요?',ARRAY['K5-1-u6-X47']::text[],false,'{"seq":6,"concept":"K5-1-u6-C47","difficulty":2,"kind":"mc","stem":"신화에서 자주 나타나는 특징은 어느 것인가요?","options":[{"t":"비범한 탄생과 시련, 그리고 뜻밖의 도움","correct":true},{"t":"모든 사건이 날짜까지 정확하다","mis":"K5-1-u6-X47"},{"t":"평범한 사람의 하루를 그린다","mis":"K5-1-u6-X47"},{"t":"누구나 겪는 일만 나온다","mis":"K5-1-u6-X47"}],"explanation":["날짜가 정확하지 않아요.","평범한 하루가 아니에요.","놀라운 일이 일어나요."]}'::jsonb),
('g5_1_kor_u6_L10_basic#7','kor',5,1,'u6','L10','g5_1_kor_u6_L10_basic','lesson_basic','K5-1-u6-C44',2,'mc','auto','왕이 주몽에게 말 먹이는 일을 시킨 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X44']::text[],false,'{"seq":7,"concept":"K5-1-u6-C44","difficulty":2,"kind":"mc","stem":"왕이 주몽에게 말 먹이는 일을 시킨 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"큰 뜻을 품지 못하게 하려고","correct":true},{"t":"말타기 실력을 길러 주려고","mis":"K5-1-u6-X44"},{"t":"좋은 말을 선물하려고","mis":"K5-1-u6-X44"},{"t":"주몽이 말을 좋아해서","mis":"K5-1-u6-X44"}],"explanation":["실력을 키워 주려는 게 아니에요.","선물이 아니에요.","태자의 말을 들은 뒤였어요."],"asset":{"type":"passage","lines":["주몽의 재주는 왕자들보다 단연 뛰어났다.","태자 대소는 주몽을 없애야 후환이 없다고 왕에게 말했다.","왕은 주몽에게 말 먹이는 일을 시켰다.","주몽은 가장 좋은 말에게 일부러 먹이를 조금씩만 주었다.","그 말은 갈대처럼 여위어 갔고, 왕은 볼품없어진 그 말을 주몽에게 주었다.","쫓기던 주몽 앞에 강이 나타나자 자라와 물고기가 다리를 놓았다.","강을 건넌 주몽은 졸본주를 도읍으로 삼고 고구려를 세웠다."],"title":"신화 「알에서 태어난 아이」 ③"}}'::jsonb),
('g5_1_kor_u6_L10_basic#8','kor',5,1,'u6','L10','g5_1_kor_u6_L10_basic','lesson_basic','K5-1-u6-C45',2,'blank','auto','빈칸에 알맞은 낱말은 어느 것인가요? 「주몽의 재주는 왕자들보다 (　　) 뛰어났다.」',ARRAY['K5-1-u6-X45']::text[],false,'{"seq":8,"concept":"K5-1-u6-C45","difficulty":2,"kind":"blank","stem":"빈칸에 알맞은 낱말은 어느 것인가요? 「주몽의 재주는 왕자들보다 (　　) 뛰어났다.」","options":[{"t":"단연","correct":true},{"t":"후환","mis":"K5-1-u6-X45"},{"t":"도읍","mis":"K5-1-u6-X45"},{"t":"태자","mis":"K5-1-u6-X45"}],"explanation":["후환은 뒷날의 걱정이에요.","도읍은 곳을 가리켜요.","여럿 가운데 뚜렷하게라는 뜻이에요."]}'::jsonb),
('g5_1_kor_u6_L10_basic#9','kor',5,1,'u6','L10','g5_1_kor_u6_L10_basic','lesson_basic','K5-1-u6-C48',2,'mc','auto','주몽 · 박혁거세 · 프로메테우스 이야기의 닮은 점은 어느 것인가요?',ARRAY['K5-1-u6-X48','K5-1-u6-X43']::text[],false,'{"seq":9,"concept":"K5-1-u6-C48","difficulty":2,"kind":"mc","stem":"주몽 · 박혁거세 · 프로메테우스 이야기의 닮은 점은 어느 것인가요?","options":[{"t":"보통 사람과 다른 특별한 인물이 나온다","correct":true},{"t":"모두 같은 나라의 이야기이다","mis":"K5-1-u6-X48"},{"t":"모두 알에서 태어난다","mis":"K5-1-u6-X48"},{"t":"모두 요즘 일어난 일이다","mis":"K5-1-u6-X43"}],"explanation":["나라가 서로 달라요.","프로메테우스는 알에서 태어나지 않았어요.","특별한 인물이 나와요."],"asset":{"type":"passage","lines":["박혁거세 — 우물가에 내려온 빛 곁에 흰말과 큰 알이 있었다.","알에서 빛나는 사내아이가 태어나 자라서 왕이 되었고, 신라가 시작되었다.","프로메테우스 — 옛날 사람들에게는 불이 없어 추운 밤에 떨었다.","프로메테우스는 몰래 불을 가져와 사람들에게 건넸다.","사람들은 따뜻해졌지만 프로메테우스는 그 일로 벌을 받았다."],"title":"신화 두 편 더"}}'::jsonb),
('g5_1_kor_u6_L10_basic#10','kor',5,1,'u6','L10','g5_1_kor_u6_L10_basic','lesson_basic','K5-1-u6-C49',3,'mc','auto','세 신화를 읽고 감상을 나눌 때 알맞은 생각은 어느 것인가요?',ARRAY['K5-1-u6-X49','K5-1-u6-X40']::text[],false,'{"seq":10,"concept":"K5-1-u6-C49","difficulty":3,"kind":"mc","stem":"세 신화를 읽고 감상을 나눌 때 알맞은 생각은 어느 것인가요?","options":[{"t":"같은 장면을 골라도 느낀 것이 다를 수 있으니 그 다름을 나눈다","correct":true},{"t":"같은 장면을 골랐다면 느낀 것도 같아야 한다","mis":"K5-1-u6-X49"},{"t":"누구의 감상이 맞는지 가려야 한다","mis":"K5-1-u6-X49"},{"t":"가장 많은 친구가 고른 장면이 정답이다","mis":"K5-1-u6-X40"}],"explanation":["느낌은 다를 수 있어요.","맞고 틀림을 가리지 않아요.","정답 장면은 없어요."]}'::jsonb),
