('g5_1_kor_u6_review_b#10','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C37',2,'match','auto','「마지막 주자」의 표현과 그 느낌을 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u6-C37","difficulty":2,"kind":"match","stem":"「마지막 주자」의 표현과 그 느낌을 알맞게 이으세요.","pairs":[{"l":"가슴이 북처럼 둥둥 울렸다","r":"몹시 긴장된다"},{"l":"운동장이 끝없는 사막 같았다","r":"막막하고 쓸쓸하다"},{"l":"손은 갓 구운 빵처럼 따뜻했다","r":"포근하고 위로가 된다"}],"mis":"K5-1-u6-X37","explanation":["출발선의 긴장이에요.","진 뒤의 막막함이에요.","친구의 위로예요."]}'::jsonb),
('g5_1_kor_u6_review_b#11','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C49',2,'mc','auto','지담이와 나봄이의 감상에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K5-1-u6-X49']::text[],false,'{"seq":11,"concept":"K5-1-u6-C49","difficulty":2,"kind":"mc","stem":"지담이와 나봄이의 감상에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"같은 장면을 골랐지만 느낀 것이 서로 다르다","correct":true},{"t":"나봄이의 감상은 틀렸다","mis":"K5-1-u6-X49"},{"t":"두 사람은 다른 장면을 골랐다","mis":"K5-1-u6-X49"},{"t":"두 사람의 느낌은 똑같다","mis":"K5-1-u6-X49"}],"explanation":["틀린 감상이 아니에요.","같은 장면이에요.","느낌은 달랐어요."],"asset":{"type":"speech","turns":[{"who":"지담","text":"나는 우람이가 손을 잡아 준 장면이 제일 마음에 남았어. 진 것보다 함께 달린 게 중요하다는 걸 알았거든."},{"who":"나봄","text":"나도 그 장면을 골랐는데 느낌은 좀 달라. 넘어진 우람이가 미안한 마음을 용기 내어 전한 것 같아서 찡했어."},{"who":"지담","text":"같은 장면인데 너는 우람이의 마음을 보았구나."}]}}'::jsonb),
('g5_1_kor_u6_review_b#12','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C23',2,'mc','auto','「웅덩이를 만나면 / 오리처럼 뒤뚱뒤뚱 건너간다」처럼 끊어 읽으면 어떻게 되나요?',ARRAY['K5-1-u6-X23']::text[],false,'{"seq":12,"concept":"K5-1-u6-C23","difficulty":2,"kind":"mc","stem":"「웅덩이를 만나면 / 오리처럼 뒤뚱뒤뚱 건너간다」처럼 끊어 읽으면 어떻게 되나요?","options":[{"t":"뒤의 「오리처럼 뒤뚱뒤뚱」에 힘이 실려 건너는 모습이 살아난다","correct":true},{"t":"시의 뜻이 틀려진다","mis":"K5-1-u6-X23"},{"t":"어디서 끊어도 느낌이 같다","mis":"K5-1-u6-X23"},{"t":"끊어 읽으면 낭송이 아니다","mis":"K5-1-u6-X23"}],"explanation":["뜻이 틀려지지 않아요.","쉬는 곳에 따라 달라요.","쉰 뒤의 말에 힘이 실려요."]}'::jsonb),
('g5_1_kor_u6_review_b#13','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C30',2,'mc','auto','예솜이가 「내 장화는 작은 배 두 척이다」를 만든 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X30','K5-1-u6-X29']::text[],false,'{"seq":13,"concept":"K5-1-u6-C30","difficulty":2,"kind":"mc","stem":"예솜이가 「내 장화는 작은 배 두 척이다」를 만든 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"장화 → 물 위를 건너게 해 준다 → 배 → 둘 다 물을 건넌다 → 작은 배 두 척이다","correct":true},{"t":"배 → 장화 → 작은 배 두 척이다 → 둘 다 물을 건넌다","mis":"K5-1-u6-X30"},{"t":"작은 배 두 척이다 → 장화 → 배 → 물 위를 건너게 해 준다","mis":"K5-1-u6-X30"},{"t":"장화 → 노란색 → 배 → 작은 배 두 척이다","mis":"K5-1-u6-X29"}],"explanation":["대상부터 정해요.","표현은 마지막이에요.","특징을 살핀 뒤 빗댈 것을 정해요."]}'::jsonb),
('g5_1_kor_u6_review_b#14','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C36',2,'mc','auto','「조개와 황새」에 쓰인 비유적 표현은 어느 것인가요?',ARRAY['K5-1-u6-X36']::text[],false,'{"seq":14,"concept":"K5-1-u6-C36","difficulty":2,"kind":"mc","stem":"「조개와 황새」에 쓰인 비유적 표현은 어느 것인가요?","options":[{"t":"조개는 덫처럼 입을 다물었습니다","correct":true},{"t":"큰 조개가 햇볕을 쬐고 있었습니다","mis":"K5-1-u6-X36"},{"t":"어부가 둘을 다 거두어 갔습니다","mis":"K5-1-u6-X36"},{"t":"왕은 계획을 접었다","mis":"K5-1-u6-X36"}],"explanation":["있었던 일 그대로예요.","빗댄 것이 없어요.","입을 다문 모습을 덫에 견주었어요."],"asset":{"type":"passage","lines":["여러 나라가 이웃해 있던 아주 오래전의 일이다.","옆 나라가 쳐들어오려 하자 한 나라 왕은 말솜씨 좋은 신하를 보냈다.","신하는 옆 나라 왕에게 이런 이야기를 들려주었다.","「강가에서 큰 조개가 입을 벌리고 햇볕을 쬐고 있었습니다.」","「황새가 돌팔매처럼 날아와 쪼자 조개는 덫처럼 입을 다물었습니다.」","「둘이 버티는 사이 지나가던 어부가 둘을 다 거두어 갔습니다.」","이야기를 들은 왕은 이웃 나라를 치려던 계획을 접었다."],"title":"이야기 「조개와 황새」"}}'::jsonb),
('g5_1_kor_u6_review_b#15','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C57',2,'mc','auto','지담이가 등대지기가 무엇인지 물은 것은 어떤 듣기 방법인가요?',ARRAY['K5-1-u6-X57','K5-1-u6-X58']::text[],false,'{"seq":15,"concept":"K5-1-u6-C57","difficulty":2,"kind":"mc","stem":"지담이가 등대지기가 무엇인지 물은 것은 어떤 듣기 방법인가요?","options":[{"t":"질문하며 듣기","correct":true},{"t":"흘려듣기","mis":"K5-1-u6-X57"},{"t":"골라 듣기","mis":"K5-1-u6-X58"},{"t":"따지며 듣기","mis":"K5-1-u6-X58"}],"explanation":["흘려듣지 않았어요.","골라 듣지 않았어요.","모르는 말을 물었어요."],"asset":{"type":"speech","turns":[{"who":"휘린","text":"어제 도서관에서 빌린 책 이야기인데, 주인공이 마지막에 집으로 돌아가지 않고 등대지기가 돼."},{"who":"지담","text":"등대지기가 뭐야? 처음 듣는 말이야."},{"who":"휘린","text":"등대를 지키며 불을 밝히는 사람이야."},{"who":"지담","text":"그러니까 주인공이 집 대신 남의 길을 밝혀 주는 일을 고른 거구나. 내가 이해한 게 맞아?"}]}}'::jsonb),
('g5_1_kor_u6_review_b#16','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C34',2,'mc','auto','하담이와 나봄이가 똑같이 장화를 시로 쓴다면 어떻게 될까요?',ARRAY['K5-1-u6-X34']::text[],false,'{"seq":16,"concept":"K5-1-u6-C34","difficulty":2,"kind":"mc","stem":"하담이와 나봄이가 똑같이 장화를 시로 쓴다면 어떻게 될까요?","options":[{"t":"장화를 무엇에 빗댈지는 저마다 다를 수 있다","correct":true},{"t":"둘 다 반드시 배에 빗대야 한다","mis":"K5-1-u6-X34"},{"t":"늦게 쓴 사람이 다르게 빗대면 틀린다","mis":"K5-1-u6-X34"},{"t":"빗댈 것은 장화마다 하나로 정해져 있다","mis":"K5-1-u6-X34"}],"explanation":["정해진 비유는 없어요.","틀린 것이 아니에요.","사람마다 보는 눈이 달라요."]}'::jsonb),
('g5_1_kor_u6_review_b#17','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C41',3,'error','auto','「마지막 주자」의 인상적인 부분을 말한 친구들이에요. 근거가 없는 말은 어느 것인가요?',ARRAY['K5-1-u6-X41','K5-1-u6-X40']::text[],false,'{"seq":17,"concept":"K5-1-u6-C41","difficulty":3,"kind":"error","stem":"「마지막 주자」의 인상적인 부분을 말한 친구들이에요. 근거가 없는 말은 어느 것인가요?","options":[{"t":"「그 이야기는 그냥 다 좋았어.」","correct":true,"mis_target":"K5-1-u6-X41"},{"t":"「손을 잡은 장면이 좋았어. 우람이가 고맙다고 말해서 마음이 따뜻해졌거든.」","mis":"K5-1-u6-X41"},{"t":"「사막 같았다는 표현이 기억에 남아. 서림이의 막막함이 느껴졌어.」","mis":"K5-1-u6-X40"}],"explanation":["장면과 까닭이 있어요.","표현과 까닭이 있어요.","어느 대목 때문인지 없어요."]}'::jsonb),
