('g5_1_kor_u6_review_c#20','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C48',3,'mc','auto','주몽 · 박혁거세 · 프로메테우스 이야기가 모두 설명하는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X48']::text[],false,'{"seq":20,"concept":"K5-1-u6-C48","difficulty":3,"kind":"mc","stem":"주몽 · 박혁거세 · 프로메테우스 이야기가 모두 설명하는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"나라나 사람들의 삶에 무언가가 처음 시작된 일","correct":true},{"t":"주인공이 모두 알에서 태어난 일","mis":"K5-1-u6-X48"},{"t":"모두 같은 나라에서 일어난 일","mis":"K5-1-u6-X48"},{"t":"주인공이 모두 벌을 받은 일","mis":"K5-1-u6-X48"}],"explanation":["프로메테우스는 알에서 태어나지 않았어요.","나라가 서로 달라요.","무언가의 시작을 풀어요."],"asset":{"type":"passage","lines":["박혁거세 — 우물가에 내려온 빛 곁에 흰말과 큰 알이 있었다.","알에서 빛나는 사내아이가 태어나 자라서 왕이 되었고, 신라가 시작되었다.","프로메테우스 — 옛날 사람들에게는 불이 없어 추운 밤에 떨었다.","프로메테우스는 몰래 불을 가져와 사람들에게 건넸다.","사람들은 따뜻해졌지만 프로메테우스는 그 일로 벌을 받았다."],"title":"신화 두 편 더"}}'::jsonb),
('g5_1_kor_u6_review_c#21','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C51',3,'mc','auto','「노란 장화」로 책갈피를 만들 때 담을 표현으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X51']::text[],false,'{"seq":21,"concept":"K5-1-u6-C51","difficulty":3,"kind":"mc","stem":"「노란 장화」로 책갈피를 만들 때 담을 표현으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"내 장화는 작은 배 두 척이다","correct":true},{"t":"비 오는 날 현관에 선 노란 장화","mis":"K5-1-u6-X51"},{"t":"집에 오면","mis":"K5-1-u6-X51"},{"t":"흙탕물이 튀어도","mis":"K5-1-u6-X51"}],"explanation":["장면만 말했어요.","한 줄로 장면이 떠오르지 않아요.","빗대어 장면이 떠올라요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb),
('g5_1_kor_u6_review_c#22','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C20',3,'mc','auto','「장화는 젖은 몸을 말리며 다음 비를 기다린다」를 쓴 예솜이의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X20']::text[],false,'{"seq":22,"concept":"K5-1-u6-C20","difficulty":3,"kind":"mc","stem":"「장화는 젖은 몸을 말리며 다음 비를 기다린다」를 쓴 예솜이의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"비 오는 날이 다시 오기를 기다리는 즐거운 마음","correct":true},{"t":"비가 싫어 장화를 버리고 싶은 마음","mis":"K5-1-u6-X20"},{"t":"장화가 젖어 속상한 마음","mis":"K5-1-u6-X20"},{"t":"장화를 새로 사고 싶은 마음","mis":"K5-1-u6-X20"}],"explanation":["싫어하는 마음이 아니에요.","속상한 게 아니에요.","다음 비를 기다려요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb),
('g5_1_kor_u6_review_c#23','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C33',4,'essay','teacher','「노란 장화」에 감상 쪽지를 쓰세요. 어느 표현이 왜 좋았는지와 더 좋은 생각을 함께 넣으세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u6-C33","difficulty":4,"kind":"essay","stem":"「노란 장화」에 감상 쪽지를 쓰세요. 어느 표현이 왜 좋았는지와 더 좋은 생각을 함께 넣으세요.","answer_guide":{"answer":"예: 「웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다」가 좋았어. 장화를 신고 조심조심 걷는 모습이 오리처럼 귀엽게 떠올랐거든. 웅덩이에 비친 하늘 이야기도 한 줄 있으면 더 좋겠어.","scoring_points":["좋았던 표현을 골랐는가","왜 좋았는지 썼는가","더 좋은 생각을 적었는가"]},"explanation":["어느 표현인가요?","왜 좋았나요?","다음 시를 돕는 생각을 적어요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb),
('g5_1_kor_u6_review_c#24','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C39',4,'essay','teacher','「마지막 주자」를 줄거리와 서림이의 마음 변화를 중심으로 세 문장으로 간추리세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u6-C39","difficulty":4,"kind":"essay","stem":"「마지막 주자」를 줄거리와 서림이의 마음 변화를 중심으로 세 문장으로 간추리세요.","answer_guide":{"answer":"예: 운동회 이어달리기에서 마지막 주자인 서림이는 우람이가 넘어져 맨 뒤로 처진 채 달렸다. 결승선을 지나 막막해하던 서림이에게 우람이가 다가와 끝까지 달려 줘서 고맙다며 손을 잡았다. 서림이는 그제야 위로받아 웃었다.","scoring_points":["일어난 일을 차례대로 썼는가","서림이의 마음 변화를 넣었는가","세 문장으로 간추렸는가"]},"explanation":["무슨 일이 있었나요?","마음은 어떻게 바뀌었나요?","세 문장으로 줄여요."]}'::jsonb),
('g5_1_kor_u6_review_c#25','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C58',4,'essay','teacher','나윤이의 듣기 태도에서 아쉬운 점을 쓰고, 잘 듣는 방법을 써서 나윤이의 속마음을 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u6-C58","difficulty":4,"kind":"essay","stem":"나윤이의 듣기 태도에서 아쉬운 점을 쓰고, 잘 듣는 방법을 써서 나윤이의 속마음을 고쳐 쓰세요.","answer_guide":{"answer":"예: 나윤이는 내용이 많다고 처음부터 흘려들으려 해서 재하가 서운했을 것이다. 「내용이 많으니 속으로 간추리며 듣고, 기억이 안 나는 부분은 다시 물어봐야지.」로 고쳐 쓸 수 있다.","scoring_points":["아쉬운 점을 썼는가","잘 듣는 방법을 썼는가","속마음을 고쳐 썼는가"]},"explanation":["나윤이는 어떻게 들었나요?","어떤 방법이 필요할까요?","속마음을 바꾸어 써요."],"asset":{"type":"speech","turns":[{"who":"나윤","text":"어제 왜 속상했다고 했지?"},{"who":"재하","text":"방금 전에 이야기했는데……."},{"who":"나윤","text":"(속으로) 내용이 너무 많아서 다 기억하기 힘드니까 그냥 흘려듣자."}]}}'::jsonb),
('g5_1_kor_u6_review_d#1','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C57',1,'mc','auto','「확인하며 듣기」에 알맞은 말은 어느 것인가요?',ARRAY['K5-1-u6-X58']::text[],false,'{"seq":1,"concept":"K5-1-u6-C57","difficulty":1,"kind":"mc","stem":"「확인하며 듣기」에 알맞은 말은 어느 것인가요?","options":[{"t":"「내가 이해한 게 맞아?」","correct":true},{"t":"「그건 틀렸어.」","mis":"K5-1-u6-X58"},{"t":"「나중에 들을게.」","mis":"K5-1-u6-X58"},{"t":"「응, 알겠어.」 하고 넘어가기","mis":"K5-1-u6-X58"}],"explanation":["따지는 말이에요.","흘려듣는 말이에요.","이해한 것을 되물어요."]}'::jsonb),
('g5_1_kor_u6_review_d#2','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C11',1,'mc','auto','직유법에 쓰이는 견주는 말이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u6-X11']::text[],false,'{"seq":2,"concept":"K5-1-u6-C11","difficulty":1,"kind":"mc","stem":"직유법에 쓰이는 견주는 말이 아닌 것은 어느 것인가요?","options":[{"t":"그래서","correct":true},{"t":"같이","mis":"K5-1-u6-X11"},{"t":"만큼","mis":"K5-1-u6-X11"},{"t":"같은","mis":"K5-1-u6-X11"}],"explanation":["같이는 견주는 말이에요.","만큼도 견주는 말이에요.","그래서는 앞뒤를 이어요."]}'::jsonb),
('g5_1_kor_u6_review_d#3','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C36',1,'mc','auto','「마지막 주자」 ②에서 비유적 표현은 어느 것인가요?',ARRAY['K5-1-u6-X36']::text[],false,'{"seq":3,"concept":"K5-1-u6-C36","difficulty":1,"kind":"mc","stem":"「마지막 주자」 ②에서 비유적 표현은 어느 것인가요?","options":[{"t":"우람이의 손은 갓 구운 빵처럼 따뜻했다","correct":true},{"t":"서림이는 그제야 고개를 들고 웃었다","mis":"K5-1-u6-X36"},{"t":"우람이가 서림이에게 다가왔다","mis":"K5-1-u6-X36"},{"t":"우람이 무릎에 흙이 묻었다","mis":"K5-1-u6-X36"}],"explanation":["있었던 일 그대로예요.","빗댄 것이 없어요.","손을 빵에 견주었어요."],"asset":{"type":"passage","lines":["결승선을 지나고 나니 운동장이 끝없는 사막 같았다.","그때 무릎에 흙이 묻은 우람이가 다가와 서림이의 손을 꼭 잡았다.","「네가 끝까지 달려 줘서 고마워.」","우람이의 손은 갓 구운 빵처럼 따뜻했다.","서림이는 그제야 고개를 들고 웃었다."],"title":"서림의 이야기 「마지막 주자」 ②"}}'::jsonb),
('g5_1_kor_u6_review_d#4','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C55',1,'ox','auto','「조개와 황새」의 신하는 이야기로 빗대어 말해 왕이 스스로 깨닫게 했어요.',ARRAY['K5-1-u6-X55']::text[],false,'{"seq":4,"concept":"K5-1-u6-C55","difficulty":1,"kind":"ox","stem":"「조개와 황새」의 신하는 이야기로 빗대어 말해 왕이 스스로 깨닫게 했어요.","answer":"O","reason_options":[{"t":"「싸우지 마십시오」라고 바로 말하는 대신 빗대어 말했기 때문에","correct":true},{"t":"신하가 조개와 황새를 정말 데려와 보여 주었기 때문에","mis":"K5-1-u6-X55"}],"mis":"K5-1-u6-X55","explanation":["이야기를 들려주었어요.","바로 말하지 않았어요.","빗대어 말하면 스스로 깨달아요."],"asset":{"type":"passage","lines":["여러 나라가 이웃해 있던 아주 오래전의 일이다.","옆 나라가 쳐들어오려 하자 한 나라 왕은 말솜씨 좋은 신하를 보냈다.","신하는 옆 나라 왕에게 이런 이야기를 들려주었다.","「강가에서 큰 조개가 입을 벌리고 햇볕을 쬐고 있었습니다.」","「황새가 돌팔매처럼 날아와 쪼자 조개는 덫처럼 입을 다물었습니다.」","「둘이 버티는 사이 지나가던 어부가 둘을 다 거두어 갔습니다.」","이야기를 들은 왕은 이웃 나라를 치려던 계획을 접었다."],"title":"이야기 「조개와 황새」"}}'::jsonb),
