('g5_1_kor_u6_review_d#16','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C15',2,'mc','auto','「내 장화는 작은 배 두 척이다」를 직유법으로 바꾼 것은 어느 것인가요?',ARRAY['K5-1-u6-X14','K5-1-u6-X15']::text[],false,'{"seq":16,"concept":"K5-1-u6-C15","difficulty":2,"kind":"mc","stem":"「내 장화는 작은 배 두 척이다」를 직유법으로 바꾼 것은 어느 것인가요?","options":[{"t":"내 장화는 작은 배 두 척 같다","correct":true},{"t":"내 장화는 노랗다","mis":"K5-1-u6-X14"},{"t":"작은 배가 장화를 신었다","mis":"K5-1-u6-X15"},{"t":"내 장화는 배가 아니다","mis":"K5-1-u6-X15"}],"explanation":["빗대지 않았어요.","뜻이 바뀌었어요.","견주는 말을 넣어요."]}'::jsonb),
('g5_1_kor_u6_review_d#17','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C57',3,'error','auto','잘 듣기에 대해 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u6-X57']::text[],false,'{"seq":17,"concept":"K5-1-u6-C57","difficulty":3,"kind":"error","stem":"잘 듣기에 대해 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「잘 들으려면 아무 말 없이 가만히 앉아 있기만 하면 돼.」","correct":true,"mis_target":"K5-1-u6-X57"},{"t":"「모르는 말이 나오면 물어보며 들어야 해.」","mis":"K5-1-u6-X57"},{"t":"「이해한 게 맞는지 되물어 확인하면 좋아.」","mis":"K5-1-u6-X57"}],"explanation":["질문하며 듣기예요.","확인하며 듣기예요.","잘 듣기는 움직이는 일이에요."]}'::jsonb),
('g5_1_kor_u6_review_d#18','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C49',3,'mc','auto','나봄이가 같은 장면인데 느낌은 좀 다르다고 한 말에 대해 알맞은 생각은 어느 것인가요?',ARRAY['K5-1-u6-X49']::text[],false,'{"seq":18,"concept":"K5-1-u6-C49","difficulty":3,"kind":"mc","stem":"나봄이가 같은 장면인데 느낌은 좀 다르다고 한 말에 대해 알맞은 생각은 어느 것인가요?","options":[{"t":"한 장면을 두고도 다르게 새길 수 있으니 서로의 까닭을 들어 본다","correct":true},{"t":"같은 장면을 골랐으니 지담이를 따라야 한다","mis":"K5-1-u6-X49"},{"t":"둘 중 누구의 감상이 맞는지 가려야 한다","mis":"K5-1-u6-X49"},{"t":"다르게 느꼈다면 다른 장면을 다시 골라야 한다","mis":"K5-1-u6-X49"}],"explanation":["따라야 하는 게 아니에요.","맞고 틀림을 가리지 않아요.","다른 해석도 나누어요."],"asset":{"type":"speech","turns":[{"who":"지담","text":"나는 우람이가 손을 잡아 준 장면이 제일 마음에 남았어. 진 것보다 함께 달린 게 중요하다는 걸 알았거든."},{"who":"나봄","text":"나도 그 장면을 골랐는데 느낌은 좀 달라. 넘어진 우람이가 미안한 마음을 용기 내어 전한 것 같아서 찡했어."},{"who":"지담","text":"같은 장면인데 너는 우람이의 마음을 보았구나."}]}}'::jsonb),
('g5_1_kor_u6_review_d#19','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C29',3,'mc','auto','장화의 보이지 않는 특징을 살펴 새 비유를 만든다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X14','K5-1-u6-X29','K5-1-u6-X31']::text[],false,'{"seq":19,"concept":"K5-1-u6-C29","difficulty":3,"kind":"mc","stem":"장화의 보이지 않는 특징을 살펴 새 비유를 만든다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"장화는 비 오는 날 내 발을 지키는 작은 집이다","correct":true},{"t":"장화는 노란 고무 신발이다","mis":"K5-1-u6-X14"},{"t":"장화는 무릎까지 오는 길이다","mis":"K5-1-u6-X29"},{"t":"장화는 노란색 크레파스다","mis":"K5-1-u6-X31"}],"explanation":["빗대지 않았어요.","길이는 보이는 특징이에요.","지켜 주는 일을 살렸어요."]}'::jsonb),
('g5_1_kor_u6_review_d#20','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C44',3,'mc','auto','주몽이 좋은 말에게 일부러 먹이를 조금만 준 까닭은 어느 것인가요?',ARRAY['K5-1-u6-X44']::text[],false,'{"seq":20,"concept":"K5-1-u6-C44","difficulty":3,"kind":"mc","stem":"주몽이 좋은 말에게 일부러 먹이를 조금만 준 까닭은 어느 것인가요?","options":[{"t":"말이 볼품없어 보이게 해 왕이 그 말을 자기에게 주도록 하려고","correct":true},{"t":"말이 살찌는 것이 싫어서","mis":"K5-1-u6-X44"},{"t":"왕의 말을 해치려고","mis":"K5-1-u6-X44"},{"t":"먹이가 모자라서","mis":"K5-1-u6-X44"}],"explanation":["살찌는 게 싫어서가 아니에요.","해치려는 게 아니에요.","왕이 그 말을 주었어요."],"asset":{"type":"passage","lines":["주몽의 재주는 왕자들보다 단연 뛰어났다.","태자 대소는 주몽을 없애야 후환이 없다고 왕에게 말했다.","왕은 주몽에게 말 먹이는 일을 시켰다.","주몽은 가장 좋은 말에게 일부러 먹이를 조금씩만 주었다.","그 말은 갈대처럼 여위어 갔고, 왕은 볼품없어진 그 말을 주몽에게 주었다.","쫓기던 주몽 앞에 강이 나타나자 자라와 물고기가 다리를 놓았다.","강을 건넌 주몽은 졸본주를 도읍으로 삼고 고구려를 세웠다."],"title":"신화 「알에서 태어난 아이」 ③"}}'::jsonb),
('g5_1_kor_u6_review_d#21','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C50',3,'mc','auto','하담이가 책갈피 계획에서 다음으로 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X50','K5-1-u6-X53','K5-1-u6-X54']::text[],false,'{"seq":21,"concept":"K5-1-u6-C50","difficulty":3,"kind":"mc","stem":"하담이가 책갈피 계획에서 다음으로 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"뒷면 그림을 정하고 끈을 묶어 완성한다","correct":true},{"t":"작품을 다시 고르기 전에 끈부터 산다","mis":"K5-1-u6-X50"},{"t":"표현을 지우고 이야기 전체를 옮겨 적는다","mis":"K5-1-u6-X53"},{"t":"소개할 말 대신 점수를 적는다","mis":"K5-1-u6-X54"}],"explanation":["작품과 표현은 골랐어요.","한두 줄이 알맞아요.","그림과 끈이 남았어요."],"asset":{"type":"passage","lines":["고른 작품 — 서림의 이야기 「마지막 주자」","앞면 — 우람이의 손은 갓 구운 빵처럼 따뜻했다","뒷면 그림 — ?","소개할 말 — ?"],"title":"하담의 책갈피 계획"}}'::jsonb),
('g5_1_kor_u6_review_d#22','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C8',3,'mc','auto','「내 장화는 작은 배 두 척이다」에서 「두 척」이라고 한 까닭은 어느 것인가요?',ARRAY['K5-1-u6-X08']::text[],false,'{"seq":22,"concept":"K5-1-u6-C8","difficulty":3,"kind":"mc","stem":"「내 장화는 작은 배 두 척이다」에서 「두 척」이라고 한 까닭은 어느 것인가요?","options":[{"t":"장화가 두 짝이라 배 두 척에 빗대었다","correct":true},{"t":"배가 두 번 나와서","mis":"K5-1-u6-X08"},{"t":"장화를 두 번 샀기 때문에","mis":"K5-1-u6-X08"},{"t":"웅덩이가 두 개라서","mis":"K5-1-u6-X08"}],"explanation":["배는 한 번 나와요.","산 이야기가 아니에요.","장화 한 켤레는 두 짝이에요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb),
('g5_1_kor_u6_review_d#23','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C26',4,'essay','teacher','「노란 장화」를 읽고 나와 관련지어 감상한 내용을 쓰고, 지금의 나를 비 오는 날의 물건에 빗대어 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u6-C26","difficulty":4,"kind":"essay","stem":"「노란 장화」를 읽고 나와 관련지어 감상한 내용을 쓰고, 지금의 나를 비 오는 날의 물건에 빗대어 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 나도 비 오는 날 웅덩이를 첨벙첨벙 밟으며 놀았던 일이 떠올라 즐거웠다. 지금의 나는 아직 펼치지 않은 우산이다. 비가 오면 언제든 활짝 펼칠 준비가 되어 있기 때문이다.","scoring_points":["나와 관련지어 감상했는가","나를 빗대어 한 문장으로 썼는가","빗댄 까닭을 썼는가"]},"explanation":["어떤 일이 떠올랐나요?","지금의 나는?","까닭을 함께 써요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb),
('g5_1_kor_u6_review_d#24','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C42',4,'essay','teacher','「마지막 주자」를 읽고 내 삶과 이어 떠오른 생각을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u6-C42","difficulty":4,"kind":"essay","stem":"「마지막 주자」를 읽고 내 삶과 이어 떠오른 생각을 쓰세요.","answer_guide":{"answer":"예: 줄넘기 대회에서 내가 걸려 우리 모둠이 졌을 때 친구가 괜찮다고 말해 준 일이 떠올랐다. 그때 우람이처럼 나도 고마운 마음을 먼저 전했으면 좋았겠다는 생각이 들었다. 다음에는 내가 먼저 손을 내밀겠다.","scoring_points":["떠오른 내 경험을 썼는가","작품과 내 경험을 이었는가","앞으로의 생각이나 다짐을 썼는가"]},"explanation":["어떤 일이 떠올랐나요?","이야기와 어떻게 이어지나요?","어떤 생각이 들었나요?"]}'::jsonb),
('g5_1_kor_u6_review_d#25','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C56',4,'essay','teacher','「조개와 황새」에 담긴 뜻을 쓰고, 이 뜻이 우리 반 생활에서 필요한 상황을 하나 들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u6-C56","difficulty":4,"kind":"essay","stem":"「조개와 황새」에 담긴 뜻을 쓰고, 이 뜻이 우리 반 생활에서 필요한 상황을 하나 들어 쓰세요.","answer_guide":{"answer":"예: 서로 물러서지 않고 다투면 둘 다 손해를 보고 다른 쪽만 이롭다는 뜻이다. 두 모둠이 운동장을 쓰는 차례를 두고 다투다 쉬는 시간이 다 지나 버려 아무도 못 노는 상황에서 이 뜻을 떠올리면 서로 양보할 수 있다.","scoring_points":["이야기에 담긴 뜻을 썼는가","우리 반 상황을 들었는가","뜻과 상황을 알맞게 이었는가"]},"explanation":["조개와 황새는 어떻게 되었나요?","비슷한 일이 있었나요?","뜻을 떠올리면 무엇이 달라지나요?"],"asset":{"type":"passage","lines":["여러 나라가 이웃해 있던 아주 오래전의 일이다.","옆 나라가 쳐들어오려 하자 한 나라 왕은 말솜씨 좋은 신하를 보냈다.","신하는 옆 나라 왕에게 이런 이야기를 들려주었다.","「강가에서 큰 조개가 입을 벌리고 햇볕을 쬐고 있었습니다.」","「황새가 돌팔매처럼 날아와 쪼자 조개는 덫처럼 입을 다물었습니다.」","「둘이 버티는 사이 지나가던 어부가 둘을 다 거두어 갔습니다.」","이야기를 들은 왕은 이웃 나라를 치려던 계획을 접었다."],"title":"이야기 「조개와 황새」"}}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('M5-1-u1-C1','math',5,1,'u1',2,'혼합 계산식과 계산 순서 약속 — 두 번 이상의 계산이 필요한 상황을 한 줄 식으로 나타내고, 계산 순서에 따라 답이 달라질 수 있어 순서를 하나로 약속해 두었음을 알기',ARRAY['6수01-01']::text[],1),
('M5-1-u1-C2','math',5,1,'u1',2,'덧셈과 뺄셈이 섞여 있는 식 — 일이 일어난 차례대로 앞에서부터 계산하고, 순서를 바꾸면 답이 달라질 수 있음을 알기',ARRAY['6수01-01']::text[],2),
('M5-1-u1-C3','math',5,1,'u1',3,'곱셈과 나눗셈이 섞여 있는 식 — 곱셈과 나눗셈은 서로를 되돌리는 같은 자리의 계산이라 앞에서부터 차례로 계산하기',ARRAY['6수01-01']::text[],3),
('M5-1-u1-C4','math',5,1,'u1',4,'덧셈, 뺄셈, 곱셈이 섞여 있는 식 — 곱셈 부분이 이미 하나의 양(덩어리)이므로 곱셈을 먼저 계산하고 덧셈·뺄셈은 앞에서부터 하기',ARRAY['6수01-01']::text[],4),
('M5-1-u1-C5','math',5,1,'u1',5,'덧셈, 뺄셈, 나눗셈이 섞여 있는 식 — 나눗셈 부분도 하나의 양이라 나눗셈을 먼저 계산하고, 곱셈과 나눗셈은 덧셈·뺄셈보다 함께 먼저임을 알기',ARRAY['6수01-01']::text[],5),
('M5-1-u1-C6','math',5,1,'u1',6,'( )가 있는 식 — ( )는 여기까지가 한 덩어리라는 표현이라 ( ) 안을 가장 먼저 계산하고, 상황에 맞게 ( )를 넣어 식을 세우기',ARRAY['6수01-01']::text[],6),
('M5-1-u1-C7','math',5,1,'u1',7,'덧셈, 뺄셈, 곱셈, 나눗셈이 섞여 있는 식 — ( ) 안 → 곱셈·나눗셈 → 덧셈·뺄셈의 세 층 순서로 계산하고 같은 층끼리는 앞에서부터 하기',ARRAY['6수01-01']::text[],7),
('M5-1-u1-C8','math',5,1,'u1',8,'문제 해결 — 부가 가치세가 공급 가격을 10으로 나눈 몫임을 알고, 여러 물건을 산 상황을 혼합 계산식 하나로 나타내며 식을 세우는 방법이 여러 가지일 수 있음을 알기',ARRAY['6수01-01']::text[],8)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('M5-1-u1-X01','math',5,'u1',ARRAY['M5-1-u1-C1','M5-1-u1-C2','M5-1-u1-C7']::text[],'덧셈과 뺄셈이 섞인 식에서 덧셈을 먼저 하거나 뒤에서부터 계산한다(40 − 15 + 5를 40 − 20으로)','덧셈·뺄셈만 있으면 앞에서부터'),
('M5-1-u1-X02','math',5,'u1',ARRAY['M5-1-u1-C3','M5-1-u1-C7']::text[],'곱셈과 나눗셈이 섞인 식에서 곱셈을 먼저 한다(36 ÷ 6 × 2를 36 ÷ 12로)','곱셈과 나눗셈은 한 자리 — 앞에서부터'),
('M5-1-u1-X03','math',5,'u1',ARRAY['M5-1-u1-C4','M5-1-u1-C7']::text[],'덧셈·뺄셈에 곱셈이 섞였는데 앞에서부터 계산한다(5 + 3 × 4를 8 × 4로)','곱셈 부분은 이미 하나의 양 — 먼저'),
('M5-1-u1-X04','math',5,'u1',ARRAY['M5-1-u1-C5','M5-1-u1-C7']::text[],'덧셈·뺄셈에 나눗셈이 섞였는데 앞에서부터 계산한다(18 + 12 ÷ 3을 30 ÷ 3으로)','나눗셈 부분도 하나의 양 — 먼저'),
('M5-1-u1-X05','math',5,'u1',ARRAY['M5-1-u1-C3','M5-1-u1-C5','M5-1-u1-C7']::text[],'「곱셈은 먼저, 나눗셈은 나중」 또는 「곱셈이 나눗셈보다 힘이 세다」고 여긴다','곱셈과 나눗셈은 함께 먼저, 둘끼리는 앞에서부터'),
('M5-1-u1-X06','math',5,'u1',ARRAY['M5-1-u1-C6','M5-1-u1-C7','M5-1-u1-C8']::text[],'( )를 보지 않고 ( )가 없는 식처럼 계산한다','( ) 안이 가장 먼저'),
('M5-1-u1-X07','math',5,'u1',ARRAY['M5-1-u1-C6','M5-1-u1-C7']::text[],'( ) 밖의 곱셈·나눗셈을 ( ) 안보다 먼저 한다','( )는 곱셈·나눗셈보다도 앞'),
('M5-1-u1-X08','math',5,'u1',ARRAY['M5-1-u1-C7']::text[],'네 가지가 섞인 식에서 덧셈·뺄셈을 곱셈·나눗셈보다 먼저 하거나 순서를 뒤바꿔 외운다','( ) → 곱셈·나눗셈 → 덧셈·뺄셈'),
('M5-1-u1-X09','math',5,'u1',ARRAY['M5-1-u1-C1','M5-1-u1-C4','M5-1-u1-C5','M5-1-u1-C6','M5-1-u1-C8']::text[],'상황을 식으로 세울 때 한 덩어리를 묶지 않거나 연산을 잘못 고른다(함께 산 두 물건값을 ( ) 없이 뺀다)','무엇이 한 덩어리인지 먼저 찾기'),
('M5-1-u1-X10','math',5,'u1',ARRAY['M5-1-u1-C1','M5-1-u1-C2','M5-1-u1-C3','M5-1-u1-C4','M5-1-u1-C5','M5-1-u1-C6','M5-1-u1-C7','M5-1-u1-C8']::text[],'계산 순서는 맞았는데 한 걸음의 셈을 잘못한다','한 걸음씩 다시 셈해 보기'),
('M5-1-u1-X11','math',5,'u1',ARRAY['M5-1-u1-C8']::text[],'부가 가치세를 공급 가격에 10을 곱하거나 100으로 나누어 구한다','공급 가격 ÷ 10'),
('M5-1-u1-X12','math',5,'u1',ARRAY['M5-1-u1-C8']::text[],'공급 가격과 실제로 내는 돈(공급 가격 + 부가 가치세)을 같은 것으로 본다','내는 돈 = 공급 가격 + 세금'),
('M5-1-u1-X13','math',5,'u1',ARRAY['M5-1-u1-C2','M5-1-u1-C4','M5-1-u1-C5','M5-1-u1-C6','M5-1-u1-C7','M5-1-u1-C8']::text[],'□가 있는 식에서 거꾸로 계산을 잘못한다(더한 것을 또 더하거나 계산 순서를 거꾸로 되돌리지 않는다)','나중에 한 계산부터 거꾸로 되돌리기'),
('M5-1-u1-X14','math',5,'u1',ARRAY['M5-1-u1-C1','M5-1-u1-C2','M5-1-u1-C3','M5-1-u1-C4','M5-1-u1-C5','M5-1-u1-C6','M5-1-u1-C7','M5-1-u1-C8']::text[],'묻는 말을 거꾸로 읽는다 — 옳은↔잘못된, 같은↔다른, 큰↔작은','물음의 「잘못·다른·가장」에 동그라미 치기')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g5_1_math_u1_L02_basic#1','math',5,1,'u1','L02','g5_1_math_u1_L02_basic','lesson_basic','M5-1-u1-C1',1,'mc','auto','알뜰 시장에서 연우는 3000원을 들고 가서 500원짜리 지우개 2개를 샀어요. 남은 돈을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M5-1-u1-X09']::text[],true,'{"seq":1,"concept":"M5-1-u1-C1","difficulty":1,"kind":"mc","stem":"알뜰 시장에서 연우는 3000원을 들고 가서 500원짜리 지우개 2개를 샀어요. 남은 돈을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3000 − 500 × 2","correct":true},{"t":"3000 + 500 × 2","mis":"M5-1-u1-X09"},{"t":"3000 × 2 − 500","mis":"M5-1-u1-X09"},{"t":"3000 − 500 + 2","mis":"M5-1-u1-X09"}],"explanation":["지우개 값은 500원이 2개 — 500 × 2예요.","남은 돈은 가진 돈 3000원에서 지우개 값을 빼요.","두 계산을 한 줄로 이으면 3000 − 500 × 2예요."],"variant_rule":{"alt":[{"stem":"민서는 5000원을 들고 가서 800원짜리 공책 3권을 샀어요. 남은 돈을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"5000 − 800 × 3","correct":true},{"t":"5000 + 800 × 3","mis":"M5-1-u1-X09"},{"t":"5000 × 3 − 800","mis":"M5-1-u1-X09"},{"t":"5000 − 800 + 3","mis":"M5-1-u1-X09"}],"explanation":["공책 값은 800 × 3이에요.","가진 돈 5000원에서 공책 값을 빼요.","한 줄로 이으면 5000 − 800 × 3이에요."]}]}}'::jsonb),
('g5_1_math_u1_L02_basic#2','math',5,1,'u1','L02','g5_1_math_u1_L02_basic','lesson_basic','M5-1-u1-C2',1,'mc','auto','25 − 8 + 6에서 가장 먼저 계산해야 할 것은 어느 것인가요?',ARRAY['M5-1-u1-X01']::text[],true,'{"seq":2,"concept":"M5-1-u1-C2","difficulty":1,"kind":"mc","stem":"25 − 8 + 6에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"25 − 8","correct":true},{"t":"8 + 6","mis":"M5-1-u1-X01"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X01"}],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","그래서 가장 먼저 계산할 것은 25 − 8이에요.","① 25 − 8 = 17 → ② 17 + 6 = 23이에요."],"variant_rule":{"alt":[{"stem":"63 − 20 + 7에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"63 − 20","correct":true},{"t":"20 + 7","mis":"M5-1-u1-X01"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X01"}],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","가장 먼저 계산할 것은 63 − 20이에요.","① 63 − 20 = 43 → ② 43 + 7 = 50이에요."]},{"stem":"48 − 19 + 5에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"48 − 19","correct":true},{"t":"19 + 5","mis":"M5-1-u1-X01"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X01"}],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","가장 먼저 계산할 것은 48 − 19예요.","① 48 − 19 = 29 → ② 29 + 5 = 34예요."]}]}}'::jsonb),
('g5_1_math_u1_L02_basic#3','math',5,1,'u1','L02','g5_1_math_u1_L02_basic','lesson_basic','M5-1-u1-C2',1,'sa','auto','24 − 9 + 3을 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-1-u1-C2","difficulty":1,"kind":"sa","stem":"24 − 9 + 3을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 24 − 9 = 15 → ② 15 + 3 = 18이에요.","그래서 24 − 9 + 3 = 18이에요."],"variant_rule":{"alt":[{"stem":"40 − 15 + 7을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 40 − 15 = 25 → ② 25 + 7 = 32예요.","그래서 40 − 15 + 7 = 32예요."]},{"stem":"36 − 12 + 8을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 36 − 12 = 24 → ② 24 + 8 = 32예요.","그래서 36 − 12 + 8 = 32예요."]}]}}'::jsonb),
('g5_1_math_u1_L02_basic#4','math',5,1,'u1','L02','g5_1_math_u1_L02_basic','lesson_basic','M5-1-u1-C1',1,'mc','auto','여러 계산이 섞인 식에서 계산 순서를 하나로 약속하지 않으면 어떤 일이 생길까요?',ARRAY['M5-1-u1-X09','M5-1-u1-X14']::text[],false,'{"seq":4,"concept":"M5-1-u1-C1","difficulty":1,"kind":"mc","stem":"여러 계산이 섞인 식에서 계산 순서를 하나로 약속하지 않으면 어떤 일이 생길까요?","options":[{"t":"사람마다 다른 답이 나올 수 있다","correct":true},{"t":"계산이 더 빨라진다","mis":"M5-1-u1-X09"},{"t":"식을 한 줄로 쓸 수 없게 된다","mis":"M5-1-u1-X09"},{"t":"아무 일도 생기지 않는다","mis":"M5-1-u1-X14"}],"explanation":["3000 − 500 × 2를 곱셈 먼저 하면 2000, 앞에서부터 하면 5000이에요.","순서에 따라 답이 달라질 수 있어요.","그래서 누구나 같은 답을 얻도록 순서를 하나로 약속해 두었어요."]}'::jsonb),
('g5_1_math_u1_L02_basic#5','math',5,1,'u1','L02','g5_1_math_u1_L02_basic','lesson_basic','M5-1-u1-C2',2,'mc','auto','지갑에 3000원이 있었어요. 공책을 사느라 1200원을 쓰고, 심부름을 하고 500원을 받았어요. 지금 지갑에 있는 돈은 얼마인가요?',ARRAY['M5-1-u1-X01','M5-1-u1-X09']::text[],true,'{"seq":5,"concept":"M5-1-u1-C2","difficulty":2,"kind":"mc","stem":"지갑에 3000원이 있었어요. 공책을 사느라 1200원을 쓰고, 심부름을 하고 500원을 받았어요. 지금 지갑에 있는 돈은 얼마인가요?","options":[{"t":"2300원","correct":true},{"t":"1300원","mis":"M5-1-u1-X01"},{"t":"1700원","mis":"M5-1-u1-X09"},{"t":"4700원","mis":"M5-1-u1-X09"}],"explanation":["쓴 돈은 빼고 받은 돈은 더해요 — 3000 − 1200 + 500.","덧셈과 뺄셈만 섞였으니 앞에서부터 — 3000 − 1200 = 1800, 1800 + 500 = 2300.","지금 있는 돈은 2300원이에요. 뒤의 1200 + 500부터 하면 1300원으로 틀려요."],"variant_rule":{"alt":[{"stem":"지갑에 5000원이 있었어요. 간식을 사느라 2500원을 쓰고, 용돈으로 1000원을 받았어요. 지금 지갑에 있는 돈은 얼마인가요?","options":[{"t":"3500원","correct":true},{"t":"1500원","mis":"M5-1-u1-X01"},{"t":"2500원","mis":"M5-1-u1-X09"},{"t":"8500원","mis":"M5-1-u1-X09"}],"explanation":["5000 − 2500 + 1000으로 나타내요.","앞에서부터 — 5000 − 2500 = 2500, 2500 + 1000 = 3500.","3500원이에요."]}]}}'::jsonb),
('g5_1_math_u1_L02_basic#6','math',5,1,'u1','L02','g5_1_math_u1_L02_basic','lesson_basic','M5-1-u1-C2',2,'sa','auto','사탕 45개 가운데 18개를 나누어 주고, 나중에 12개를 더 받았어요. 지금 사탕은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u1-C2","difficulty":2,"kind":"sa","stem":"사탕 45개 가운데 18개를 나누어 주고, 나중에 12개를 더 받았어요. 지금 사탕은 몇 개인가요? 숫자로 쓰세요.","answer":["39","39개"],"explanation":["나누어 준 것은 빼고 받은 것은 더해요 — 45 − 18 + 12.","앞에서부터 — 45 − 18 = 27, 27 + 12 = 39.","지금 사탕은 39개예요."],"variant_rule":{"alt":[{"stem":"사탕 30개 가운데 8개를 나누어 주고, 나중에 5개를 더 받았어요. 지금 사탕은 몇 개인가요? 숫자로 쓰세요.","answer":["27","27개"],"explanation":["30 − 8 + 5로 나타내요.","앞에서부터 — 30 − 8 = 22, 22 + 5 = 27.","27개예요."]}]}}'::jsonb),
('g5_1_math_u1_L02_basic#7','math',5,1,'u1','L02','g5_1_math_u1_L02_basic','lesson_basic','M5-1-u1-C2',2,'error','auto','준서는 40 − 15 + 5를 계산해 20이라고 답했어요. 준서가 잘못한 것은 무엇인가요?',ARRAY['M5-1-u1-X01','M5-1-u1-X10','M5-1-u1-X14']::text[],true,'{"seq":7,"concept":"M5-1-u1-C2","difficulty":2,"kind":"error","stem":"준서는 40 − 15 + 5를 계산해 20이라고 답했어요. 준서가 잘못한 것은 무엇인가요?","options":[{"t":"뒤의 15 + 5를 먼저 했다","correct":true,"mis_target":"M5-1-u1-X01"},{"t":"40 − 15를 잘못 뺐다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["덧셈과 뺄셈만 있으면 앞에서부터 계산해요.","40 − 15 = 25, 25 + 5 = 30이 맞아요.","준서는 15 + 5 = 20을 먼저 해서 40 − 20 = 20이 나왔어요."],"variant_rule":{"alt":[{"stem":"하윤이는 52 − 17 + 9를 계산해 26이라고 답했어요. 하윤이가 잘못한 것은 무엇인가요?","options":[{"t":"뒤의 17 + 9를 먼저 했다","correct":true,"mis_target":"M5-1-u1-X01"},{"t":"52 − 17을 잘못 뺐다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["앞에서부터 계산해요.","52 − 17 = 35, 35 + 9 = 44가 맞아요.","하윤이는 17 + 9 = 26을 먼저 해서 52 − 26 = 26이 나왔어요."]}]}}'::jsonb),
('g5_1_math_u1_L02_basic#8','math',5,1,'u1','L02','g5_1_math_u1_L02_basic','lesson_basic','M5-1-u1-C2',2,'ox','auto','덧셈과 뺄셈이 섞여 있는 식에서는 덧셈을 먼저 계산해야 해요.',ARRAY['M5-1-u1-X01']::text[],true,'{"seq":8,"concept":"M5-1-u1-C2","difficulty":2,"kind":"ox","stem":"덧셈과 뺄셈이 섞여 있는 식에서는 덧셈을 먼저 계산해야 해요.","answer":"X","reason_options":[{"t":"덧셈과 뺄셈만 섞이면 일이 일어난 차례대로 앞에서부터 계산해서","correct":true},{"t":"덧셈이 뺄셈보다 먼저라서","mis":"M5-1-u1-X01"}],"mis":"M5-1-u1-X01","explanation":["덧셈과 뺄셈은 같은 자리의 계산이에요.","그래서 앞에서부터 차례로 계산해요.","예: 40 − 15 + 5 = 25 + 5 = 30이에요."],"variant_rule":{"alt":[{"stem":"덧셈과 뺄셈이 섞여 있는 식에서는 뒤에서부터 계산해도 언제나 답이 같아요.","answer":"X","reason_options":[{"t":"뒤에서부터 하면 답이 달라질 수 있어서 앞에서부터 계산해요","correct":true},{"t":"덧셈과 뺄셈은 순서를 바꿔도 늘 같아서","mis":"M5-1-u1-X01"}],"explanation":["3000 − 1200 + 500을 앞에서부터 하면 2300이에요.","뒤의 1200 + 500부터 하면 1300이 나와요.","순서를 바꾸면 답이 달라질 수 있어요."]}]}}'::jsonb),
