('g5_1_math_u1_L02_basic#10','math',5,1,'u1','L02','g5_1_math_u1_L02_basic','lesson_basic','M5-1-u1-C2',3,'mc','auto','60 − 20 + 10과 60 − 20 − 10의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X01','M5-1-u1-X14']::text[],true,'{"seq":10,"concept":"M5-1-u1-C2","difficulty":3,"kind":"mc","stem":"60 − 20 + 10과 60 − 20 − 10의 계산 결과의 차는 얼마인가요?","options":[{"t":"20","correct":true},{"t":"0","mis":"M5-1-u1-X01"},{"t":"50","mis":"M5-1-u1-X14"},{"t":"30","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","60 − 20 + 10 = 50 · 60 − 20 − 10 = 30","두 결과의 차는 50 − 30 = 20이에요."],"variant_rule":{"alt":[{"stem":"80 − 30 + 15와 80 − 30 − 15의 계산 결과의 차는 얼마인가요?","options":[{"t":"30","correct":true},{"t":"0","mis":"M5-1-u1-X01"},{"t":"65","mis":"M5-1-u1-X14"},{"t":"35","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","80 − 30 + 15 = 65 · 80 − 30 − 15 = 35","두 결과의 차는 65 − 35 = 30이에요."]}]}}'::jsonb),
('g5_1_math_u1_L02_challenge#1','math',5,1,'u1','L02','g5_1_math_u1_L02_challenge','lesson_challenge','M5-1-u1-C2',2,'mc','auto','93 − 45 + 28 − 16을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X01','M5-1-u1-X10']::text[],true,'{"seq":1,"concept":"M5-1-u1-C2","difficulty":2,"kind":"mc","stem":"93 − 45 + 28 − 16을 계산하면 얼마인가요?","options":[{"t":"60","correct":true},{"t":"4","mis":"M5-1-u1-X01"},{"t":"70","mis":"M5-1-u1-X10"},{"t":"50","mis":"M5-1-u1-X10"}],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 93 − 45 = 48 → ② 48 + 28 = 76 → ③ 76 − 16 = 60이에요.","그래서 93 − 45 + 28 − 16 = 60이에요."],"variant_rule":{"alt":[{"stem":"81 − 37 + 24 − 19를 계산하면 얼마인가요?","options":[{"t":"49","correct":true},{"t":"1","mis":"M5-1-u1-X01"},{"t":"59","mis":"M5-1-u1-X10"},{"t":"39","mis":"M5-1-u1-X10"}],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 81 − 37 = 44 → ② 44 + 24 = 68 → ③ 68 − 19 = 49예요.","그래서 81 − 37 + 24 − 19 = 49예요."]},{"stem":"76 − 28 − 19 + 35를 계산하면 얼마인가요?","options":[{"t":"64","correct":true},{"t":"74","mis":"M5-1-u1-X10"},{"t":"54","mis":"M5-1-u1-X10"},{"t":"66","mis":"M5-1-u1-X10"}],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 76 − 28 = 48 → ② 48 − 19 = 29 → ③ 29 + 35 = 64예요.","그래서 76 − 28 − 19 + 35 = 64예요."]}]}}'::jsonb),
('g5_1_math_u1_L02_challenge#2','math',5,1,'u1','L02','g5_1_math_u1_L02_challenge','lesson_challenge','M5-1-u1-C1',2,'mc','auto','18 + 6 − 4를 계산하면 20이에요. 바르게 계산한 순서는 어느 것인가요?',ARRAY['M5-1-u1-X01','M5-1-u1-X14']::text[],false,'{"seq":2,"concept":"M5-1-u1-C1","difficulty":2,"kind":"mc","stem":"18 + 6 − 4를 계산하면 20이에요. 바르게 계산한 순서는 어느 것인가요?","options":[{"t":"18 + 6을 먼저 했다","correct":true},{"t":"6 − 4를 먼저 했다","mis":"M5-1-u1-X01"},{"t":"18 − 4를 먼저 했다","mis":"M5-1-u1-X01"},{"t":"어느 것부터 해도 다르다","mis":"M5-1-u1-X14"}],"explanation":["덧셈과 뺄셈만 섞이면 앞에서부터예요.","18 + 6 = 24, 24 − 4 = 20이에요.","이 식은 6 − 4부터 해도 20이 나오지만, 약속은 앞에서부터예요."]}'::jsonb),
('g5_1_math_u1_L02_challenge#3','math',5,1,'u1','L02','g5_1_math_u1_L02_challenge','lesson_challenge','M5-1-u1-C2',3,'mc','auto','70 − □ + 15 = 60에서 □에 알맞은 수는 얼마인가요?',ARRAY['M5-1-u1-X13','M5-1-u1-X01']::text[],true,'{"seq":3,"concept":"M5-1-u1-C2","difficulty":3,"kind":"mc","stem":"70 − □ + 15 = 60에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"25","correct":true},{"t":"45","mis":"M5-1-u1-X13"},{"t":"55","mis":"M5-1-u1-X13"},{"t":"5","mis":"M5-1-u1-X01"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 60이 되어야 해요.","거꾸로 되돌리면 □ = 25예요.","확인: 70 − 25 + 15 → ① 70 − 25 = 45 → ② 45 + 15 = 60"],"variant_rule":{"alt":[{"stem":"90 − □ + 20 = 75에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"35","correct":true},{"t":"55","mis":"M5-1-u1-X13"},{"t":"65","mis":"M5-1-u1-X13"},{"t":"15","mis":"M5-1-u1-X01"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 75가 되어야 해요.","거꾸로 되돌리면 □ = 35예요.","확인: 90 − 35 + 20 → ① 90 − 35 = 55 → ② 55 + 20 = 75"]}]}}'::jsonb),
('g5_1_math_u1_L02_challenge#4','math',5,1,'u1','L02','g5_1_math_u1_L02_challenge','lesson_challenge','M5-1-u1-C1',3,'mc','auto','다음 중 계산 순서를 바꾸면 답이 달라지는 식은 어느 것인가요?',ARRAY['M5-1-u1-X14']::text[],false,'{"seq":4,"concept":"M5-1-u1-C1","difficulty":3,"kind":"mc","stem":"다음 중 계산 순서를 바꾸면 답이 달라지는 식은 어느 것인가요?","options":[{"t":"50 − 20 + 10","correct":true},{"t":"50 + 20 + 10","mis":"M5-1-u1-X14"},{"t":"50 − 20 − 10을 앞에서부터만 계산한 것","mis":"M5-1-u1-X14"},{"t":"20 + 10 + 50","mis":"M5-1-u1-X14"}],"explanation":["덧셈만 있는 식은 순서를 바꿔도 답이 같아요.","50 − 20 + 10을 앞에서부터 하면 40, 20 + 10부터 하면 20이에요.","뺄셈 뒤에 덧셈이 오면 순서에 따라 답이 갈려요."]}'::jsonb),
('g5_1_math_u1_L02_challenge#5','math',5,1,'u1','L02','g5_1_math_u1_L02_challenge','lesson_challenge','M5-1-u1-C2',3,'error','auto','「45 − 18 + 12」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u1-X01','M5-1-u1-X14']::text[],false,'{"seq":5,"concept":"M5-1-u1-C2","difficulty":3,"kind":"error","stem":"「45 − 18 + 12」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「18 + 12를 먼저 해서 45에서 30을 빼면 돼.」","correct":true,"mis_target":"M5-1-u1-X01"},{"t":"서아 — 「45 − 18 = 27을 먼저 하고 12를 더해.」","mis":"M5-1-u1-X14"},{"t":"지호 — 「나누어 준 다음 받았으니 일어난 차례대로 해.」","mis":"M5-1-u1-X14"}],"explanation":["나누어 준 일과 받은 일은 차례로 일어났어요.","그래서 앞에서부터 — 45 − 18 = 27, 27 + 12 = 39예요.","도윤이처럼 18 + 12부터 하면 15가 되어 틀려요."]}'::jsonb),
('g5_1_math_u1_L02_challenge#6','math',5,1,'u1','L02','g5_1_math_u1_L02_challenge','lesson_challenge','M5-1-u1-C2',3,'mc','auto','버스에 34명이 타고 있었어요. 첫 정류장에서 9명이 내리고 15명이 탔어요. 식으로 나타내 계산한 것으로 알맞은 것은 어느 것인가요?',ARRAY['M5-1-u1-X09','M5-1-u1-X01']::text[],true,'{"seq":6,"concept":"M5-1-u1-C2","difficulty":3,"kind":"mc","stem":"버스에 34명이 타고 있었어요. 첫 정류장에서 9명이 내리고 15명이 탔어요. 식으로 나타내 계산한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"34 − 9 + 15 = 40","correct":true},{"t":"34 − (9 + 15) = 10","mis":"M5-1-u1-X09"},{"t":"34 + 9 − 15 = 28","mis":"M5-1-u1-X09"},{"t":"34 − 9 + 15 = 10","mis":"M5-1-u1-X01"}],"explanation":["내린 사람은 빼고 탄 사람은 더해요.","34 − 9 + 15를 앞에서부터 — 34 − 9 = 25, 25 + 15 = 40.","버스에는 40명이 있어요."],"variant_rule":{"alt":[{"stem":"도서관에 책이 52권 있었어요. 18권을 빌려 가고 7권이 돌아왔어요. 식으로 나타내 계산한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"52 − 18 + 7 = 41","correct":true},{"t":"52 − (18 + 7) = 27","mis":"M5-1-u1-X09"},{"t":"52 + 18 − 7 = 63","mis":"M5-1-u1-X09"},{"t":"52 − 18 + 7 = 27","mis":"M5-1-u1-X01"}],"explanation":["빌려 간 책은 빼고 돌아온 책은 더해요.","52 − 18 = 34, 34 + 7 = 41.","41권이에요."]}]}}'::jsonb),
('g5_1_math_u1_L02_challenge#7','math',5,1,'u1','L02','g5_1_math_u1_L02_challenge','lesson_challenge','M5-1-u1-C2',3,'mc','auto','75 − 25 + 15와 75 − (25 + 15)의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],true,'{"seq":7,"concept":"M5-1-u1-C2","difficulty":3,"kind":"mc","stem":"75 − 25 + 15와 75 − (25 + 15)의 계산 결과의 차는 얼마인가요?","options":[{"t":"30","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"65","mis":"M5-1-u1-X14"},{"t":"35","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","75 − 25 + 15 = 65 · 75 − (25 + 15) = 35","두 결과의 차는 65 − 35 = 30이에요."],"variant_rule":{"alt":[{"stem":"64 − 24 + 16과 64 − (24 + 16)의 계산 결과의 차는 얼마인가요?","options":[{"t":"32","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"56","mis":"M5-1-u1-X14"},{"t":"24","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","64 − 24 + 16 = 56 · 64 − (24 + 16) = 24","두 결과의 차는 56 − 24 = 32예요."]}]}}'::jsonb),
('g5_1_math_u1_L02_challenge#8','math',5,1,'u1','L02','g5_1_math_u1_L02_challenge','lesson_challenge','M5-1-u1-C1',4,'essay','teacher','3000 − 1200 + 500을 앞에서부터 계산한 답과 뒤의 1200 + 500부터 계산한 답을 각각 구하고, 지갑 이야기(3000원에서 1200원을 쓰고 500원을 받음)에 맞는 답은 어느 것인지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-1-u1-C1","difficulty":4,"kind":"essay","stem":"3000 − 1200 + 500을 앞에서부터 계산한 답과 뒤의 1200 + 500부터 계산한 답을 각각 구하고, 지갑 이야기(3000원에서 1200원을 쓰고 500원을 받음)에 맞는 답은 어느 것인지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 앞에서부터 하면 3000 − 1200 = 1800, 1800 + 500 = 2300이고, 뒤부터 하면 1200 + 500 = 1700, 3000 − 1700 = 1300이다. 돈을 먼저 쓰고 나중에 받았으니 일어난 차례대로 계산한 2300원이 맞다.","scoring_points":["앞에서부터 계산한 2300을 구했는가","뒤부터 계산한 1300을 구했는가","일이 일어난 차례대로 계산해야 한다는 까닭을 썼는가"]},"explanation":["앞에서부터 — 2300, 뒤부터 — 1300이에요.","돈은 먼저 쓰고 나중에 받았어요.","일어난 차례대로 계산한 2300원이 맞아요."]}'::jsonb),
('g5_1_math_u1_L02_challenge#9','math',5,1,'u1','L02','g5_1_math_u1_L02_challenge','lesson_challenge','M5-1-u1-C2',4,'essay','teacher','「덧셈과 뺄셈이 섞이면 덧셈을 먼저 해야 해.」라는 지호의 말이 맞는지 판단하고, 52 − 17 + 9를 예로 들어 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u1-C2","difficulty":4,"kind":"essay","stem":"「덧셈과 뺄셈이 섞이면 덧셈을 먼저 해야 해.」라는 지호의 말이 맞는지 판단하고, 52 − 17 + 9를 예로 들어 설명하세요.","answer_guide":{"answer":"예: 틀리다. 덧셈과 뺄셈만 섞이면 앞에서부터 차례로 계산한다. 52 − 17 + 9는 52 − 17 = 35, 35 + 9 = 44이다. 덧셈을 먼저 하면 17 + 9 = 26, 52 − 26 = 26으로 답이 달라진다.","scoring_points":["틀리다고 판단했는가","앞에서부터 계산해 44를 구했는가","덧셈을 먼저 하면 답이 달라짐(26)을 보였는가"]},"explanation":["덧셈과 뺄셈만 있으면 앞에서부터예요.","52 − 17 + 9 = 35 + 9 = 44예요.","덧셈을 먼저 하면 26으로 달라져요."]}'::jsonb),
('g5_1_math_u1_L02_challenge#10','math',5,1,'u1','L02','g5_1_math_u1_L02_challenge','lesson_challenge','M5-1-u1-C2',4,'mc','auto','□ − 18 + 25 = 60에서 □에 알맞은 수는 얼마인가요?',ARRAY['M5-1-u1-X13']::text[],true,'{"seq":10,"concept":"M5-1-u1-C2","difficulty":4,"kind":"mc","stem":"□ − 18 + 25 = 60에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"53","correct":true},{"t":"103","mis":"M5-1-u1-X13"},{"t":"67","mis":"M5-1-u1-X13"},{"t":"17","mis":"M5-1-u1-X13"}],"explanation":["□ − 18을 먼저 하고 25를 더해 60이 되었어요.","거꾸로 되돌리면 60 − 25 = 35, 35 + 18 = 53이에요.","확인: 53 − 18 + 25 = 35 + 25 = 60이에요."],"variant_rule":{"alt":[{"stem":"□ − 24 + 16 = 50에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"58","correct":true},{"t":"90","mis":"M5-1-u1-X13"},{"t":"42","mis":"M5-1-u1-X13"},{"t":"10","mis":"M5-1-u1-X13"}],"explanation":["거꾸로 되돌려요 — 50 − 16 = 34.","34 + 24 = 58이에요.","확인: 58 − 24 + 16 = 34 + 16 = 50이에요."]}]}}'::jsonb),
('g5_1_math_u1_L03_basic#1','math',5,1,'u1','L03','g5_1_math_u1_L03_basic','lesson_basic','M5-1-u1-C3',1,'mc','auto','24 ÷ 4 × 3에서 가장 먼저 계산해야 할 것은 어느 것인가요?',ARRAY['M5-1-u1-X02']::text[],true,'{"seq":1,"concept":"M5-1-u1-C3","difficulty":1,"kind":"mc","stem":"24 ÷ 4 × 3에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"24 ÷ 4","correct":true},{"t":"4 × 3","mis":"M5-1-u1-X02"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X02"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","그래서 가장 먼저 계산할 것은 24 ÷ 4예요.","① 24 ÷ 4 = 6 → ② 6 × 3 = 18이에요."],"variant_rule":{"alt":[{"stem":"36 ÷ 6 × 2에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"36 ÷ 6","correct":true},{"t":"6 × 2","mis":"M5-1-u1-X02"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X02"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","가장 먼저 계산할 것은 36 ÷ 6이에요.","① 36 ÷ 6 = 6 → ② 6 × 2 = 12예요."]},{"stem":"48 ÷ 8 × 5에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"48 ÷ 8","correct":true},{"t":"8 × 5","mis":"M5-1-u1-X02"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X02"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","가장 먼저 계산할 것은 48 ÷ 8이에요.","① 48 ÷ 8 = 6 → ② 6 × 5 = 30이에요."]}]}}'::jsonb),
('g5_1_math_u1_L03_basic#2','math',5,1,'u1','L03','g5_1_math_u1_L03_basic','lesson_basic','M5-1-u1-C3',1,'sa','auto','24 ÷ 4 × 3을 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u1-C3","difficulty":1,"kind":"sa","stem":"24 ÷ 4 × 3을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 24 ÷ 4 = 6 → ② 6 × 3 = 18이에요.","그래서 24 ÷ 4 × 3 = 18이에요."],"variant_rule":{"alt":[{"stem":"36 ÷ 9 × 7을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 36 ÷ 9 = 4 → ② 4 × 7 = 28이에요.","그래서 36 ÷ 9 × 7 = 28이에요."]},{"stem":"45 ÷ 5 × 6을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 45 ÷ 5 = 9 → ② 9 × 6 = 54예요.","그래서 45 ÷ 5 × 6 = 54예요."]}]}}'::jsonb),
('g5_1_math_u1_L03_basic#3','math',5,1,'u1','L03','g5_1_math_u1_L03_basic','lesson_basic','M5-1-u1-C3',1,'mc','auto','48 ÷ 8 × 5를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X10']::text[],true,'{"seq":3,"concept":"M5-1-u1-C3","difficulty":1,"kind":"mc","stem":"48 ÷ 8 × 5를 계산하면 얼마인가요?","options":[{"t":"30","correct":true},{"t":"40","mis":"M5-1-u1-X10"},{"t":"20","mis":"M5-1-u1-X10"},{"t":"32","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 48 ÷ 8 = 6 → ② 6 × 5 = 30이에요.","그래서 48 ÷ 8 × 5 = 30이에요."],"variant_rule":{"alt":[{"stem":"56 ÷ 7 × 4를 계산하면 얼마인가요?","options":[{"t":"32","correct":true},{"t":"2","mis":"M5-1-u1-X02"},{"t":"42","mis":"M5-1-u1-X10"},{"t":"22","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 56 ÷ 7 = 8 → ② 8 × 4 = 32예요.","그래서 56 ÷ 7 × 4 = 32예요."]},{"stem":"63 ÷ 9 × 8을 계산하면 얼마인가요?","options":[{"t":"56","correct":true},{"t":"66","mis":"M5-1-u1-X10"},{"t":"46","mis":"M5-1-u1-X10"},{"t":"58","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 63 ÷ 9 = 7 → ② 7 × 8 = 56이에요.","그래서 63 ÷ 9 × 8 = 56이에요."]}]}}'::jsonb),
('g5_1_math_u1_L03_basic#4','math',5,1,'u1','L03','g5_1_math_u1_L03_basic','lesson_basic','M5-1-u1-C3',1,'mc','auto','쿠키 24개를 접시 4개에 똑같이 나누어 담고, 그중 3접시를 교실로 가져가요. 가져가는 쿠키 수를 구하는 식은 어느 것인가요?',ARRAY['M5-1-u1-X09','M5-1-u1-X02']::text[],true,'{"seq":4,"concept":"M5-1-u1-C3","difficulty":1,"kind":"mc","stem":"쿠키 24개를 접시 4개에 똑같이 나누어 담고, 그중 3접시를 교실로 가져가요. 가져가는 쿠키 수를 구하는 식은 어느 것인가요?","options":[{"t":"24 ÷ 4 × 3","correct":true},{"t":"24 × 4 ÷ 3","mis":"M5-1-u1-X09"},{"t":"24 ÷ (4 × 3)","mis":"M5-1-u1-X02"},{"t":"24 − 4 × 3","mis":"M5-1-u1-X09"}],"explanation":["한 접시에 담긴 쿠키는 24 ÷ 4예요.","그것을 3접시만큼 모으니 × 3이에요.","이어 쓰면 24 ÷ 4 × 3이에요."],"variant_rule":{"alt":[{"stem":"귤 40개를 바구니 5개에 똑같이 나누어 담고, 그중 2바구니를 할머니께 드려요. 드리는 귤 수를 구하는 식은 어느 것인가요?","options":[{"t":"40 ÷ 5 × 2","correct":true},{"t":"40 × 5 ÷ 2","mis":"M5-1-u1-X09"},{"t":"40 ÷ (5 × 2)","mis":"M5-1-u1-X02"},{"t":"40 − 5 × 2","mis":"M5-1-u1-X09"}],"explanation":["한 바구니의 귤은 40 ÷ 5예요.","2바구니만큼 모으니 × 2예요.","40 ÷ 5 × 2예요."]}]}}'::jsonb),
('g5_1_math_u1_L03_basic#5','math',5,1,'u1','L03','g5_1_math_u1_L03_basic','lesson_basic','M5-1-u1-C3',2,'sa','auto','쿠키 24개를 접시 4개에 똑같이 나누어 담고, 그중 3접시를 교실로 가져가요. 가져가는 쿠키는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-1-u1-C3","difficulty":2,"kind":"sa","stem":"쿠키 24개를 접시 4개에 똑같이 나누어 담고, 그중 3접시를 교실로 가져가요. 가져가는 쿠키는 몇 개인가요? 숫자로 쓰세요.","answer":["18","18개"],"explanation":["24 ÷ 4 × 3을 앞에서부터 계산해요.","24 ÷ 4 = 6 — 한 접시에 6개, 6 × 3 = 18.","가져가는 쿠키는 18개예요."],"variant_rule":{"alt":[{"stem":"귤 40개를 바구니 5개에 똑같이 나누어 담고, 그중 2바구니를 할머니께 드려요. 드리는 귤은 몇 개인가요? 숫자로 쓰세요.","answer":["16","16개"],"explanation":["40 ÷ 5 × 2를 앞에서부터 계산해요.","40 ÷ 5 = 8, 8 × 2 = 16.","16개예요."]}]}}'::jsonb),
('g5_1_math_u1_L03_basic#6','math',5,1,'u1','L03','g5_1_math_u1_L03_basic','lesson_basic','M5-1-u1-C3',2,'error','auto','예린이는 36 ÷ 6 × 2를 계산해 3이라고 답했어요. 예린이가 잘못한 것은 무엇인가요?',ARRAY['M5-1-u1-X02','M5-1-u1-X10','M5-1-u1-X14']::text[],true,'{"seq":6,"concept":"M5-1-u1-C3","difficulty":2,"kind":"error","stem":"예린이는 36 ÷ 6 × 2를 계산해 3이라고 답했어요. 예린이가 잘못한 것은 무엇인가요?","options":[{"t":"뒤의 6 × 2를 먼저 했다","correct":true,"mis_target":"M5-1-u1-X02"},{"t":"36 ÷ 6을 잘못 나눴다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["곱셈과 나눗셈만 섞이면 앞에서부터 계산해요.","36 ÷ 6 = 6, 6 × 2 = 12가 맞아요.","예린이는 6 × 2 = 12를 먼저 해서 36 ÷ 12 = 3이 나왔어요."],"variant_rule":{"alt":[{"stem":"태오는 48 ÷ 4 × 2를 계산해 6이라고 답했어요. 태오가 잘못한 것은 무엇인가요?","options":[{"t":"뒤의 4 × 2를 먼저 했다","correct":true,"mis_target":"M5-1-u1-X02"},{"t":"48 ÷ 4를 잘못 나눴다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["앞에서부터 계산해요.","48 ÷ 4 = 12, 12 × 2 = 24가 맞아요.","태오는 4 × 2를 먼저 해서 48 ÷ 8 = 6이 나왔어요."]}]}}'::jsonb),
('g5_1_math_u1_L03_basic#7','math',5,1,'u1','L03','g5_1_math_u1_L03_basic','lesson_basic','M5-1-u1-C3',2,'ox','auto','곱셈과 나눗셈이 섞여 있는 식에서는 곱셈을 먼저 계산해요.',ARRAY['M5-1-u1-X05']::text[],false,'{"seq":7,"concept":"M5-1-u1-C3","difficulty":2,"kind":"ox","stem":"곱셈과 나눗셈이 섞여 있는 식에서는 곱셈을 먼저 계산해요.","answer":"X","reason_options":[{"t":"곱셈과 나눗셈은 서로를 되돌리는 같은 자리의 계산이라 앞에서부터 계산해서","correct":true},{"t":"곱셈이 나눗셈보다 힘이 세서","mis":"M5-1-u1-X05"}],"mis":"M5-1-u1-X05","explanation":["곱셈이 나눗셈보다 힘이 센 게 아니에요.","둘은 같은 자리라서 일어난 차례대로 — 앞에서부터 해요.","예: 24 ÷ 4 × 3 = 6 × 3 = 18이에요."]}'::jsonb),
('g5_1_math_u1_L03_basic#8','math',5,1,'u1','L03','g5_1_math_u1_L03_basic','lesson_basic','M5-1-u1-C3',2,'match','auto','계산식과 계산 결과를 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u1-C3","difficulty":2,"kind":"match","stem":"계산식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"36 ÷ 4 × 3","r":"27"},{"l":"72 ÷ 8 × 5","r":"45"},{"l":"28 ÷ 7 × 9","r":"36"}],"mis":"M5-1-u1-X02","explanation":["식마다 계산 순서를 지켜 셈해요.","36 ÷ 4 × 3 = 27 · 72 ÷ 8 × 5 = 45 · 28 ÷ 7 × 9 = 36","곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 계산식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"42 ÷ 6 × 4","r":"28"},{"l":"54 ÷ 9 × 7","r":"42"},{"l":"35 ÷ 5 × 3","r":"21"}],"explanation":["식마다 계산 순서를 지켜 셈해요.","42 ÷ 6 × 4 = 28 · 54 ÷ 9 × 7 = 42 · 35 ÷ 5 × 3 = 21","곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요."]}]}}'::jsonb),
('g5_1_math_u1_L03_basic#9','math',5,1,'u1','L03','g5_1_math_u1_L03_basic','lesson_basic','M5-1-u1-C3',2,'mc','auto','7 × 8 ÷ 4를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X10']::text[],true,'{"seq":9,"concept":"M5-1-u1-C3","difficulty":2,"kind":"mc","stem":"7 × 8 ÷ 4를 계산하면 얼마인가요?","options":[{"t":"14","correct":true},{"t":"24","mis":"M5-1-u1-X10"},{"t":"4","mis":"M5-1-u1-X10"},{"t":"16","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 7 × 8 = 56 → ② 56 ÷ 4 = 14예요.","그래서 7 × 8 ÷ 4 = 14예요."],"variant_rule":{"alt":[{"stem":"6 × 9 ÷ 3을 계산하면 얼마인가요?","options":[{"t":"18","correct":true},{"t":"28","mis":"M5-1-u1-X10"},{"t":"8","mis":"M5-1-u1-X10"},{"t":"20","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 6 × 9 = 54 → ② 54 ÷ 3 = 18이에요.","그래서 6 × 9 ÷ 3 = 18이에요."]},{"stem":"9 × 4 ÷ 6을 계산하면 얼마인가요?","options":[{"t":"6","correct":true},{"t":"16","mis":"M5-1-u1-X10"},{"t":"8","mis":"M5-1-u1-X10"},{"t":"4","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 9 × 4 = 36 → ② 36 ÷ 6 = 6이에요.","그래서 9 × 4 ÷ 6 = 6이에요."]}]}}'::jsonb),
('g5_1_math_u1_L03_basic#10','math',5,1,'u1','L03','g5_1_math_u1_L03_basic','lesson_basic','M5-1-u1-C3',3,'mc','auto','48 ÷ 4 × 2와 48 ÷ (4 × 2)의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],true,'{"seq":10,"concept":"M5-1-u1-C3","difficulty":3,"kind":"mc","stem":"48 ÷ 4 × 2와 48 ÷ (4 × 2)의 계산 결과의 차는 얼마인가요?","options":[{"t":"18","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"24","mis":"M5-1-u1-X14"},{"t":"6","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","48 ÷ 4 × 2 = 24 · 48 ÷ (4 × 2) = 6","두 결과의 차는 24 − 6 = 18이에요."],"variant_rule":{"alt":[{"stem":"60 ÷ 5 × 3과 60 ÷ (5 × 3)의 계산 결과의 차는 얼마인가요?","options":[{"t":"32","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"36","mis":"M5-1-u1-X14"},{"t":"4","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","60 ÷ 5 × 3 = 36 · 60 ÷ (5 × 3) = 4","두 결과의 차는 36 − 4 = 32예요."]}]}}'::jsonb),
('g5_1_math_u1_L03_challenge#1','math',5,1,'u1','L03','g5_1_math_u1_L03_challenge','lesson_challenge','M5-1-u1-C3',2,'mc','auto','96 ÷ 8 × 3 ÷ 4를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X02','M5-1-u1-X10']::text[],true,'{"seq":1,"concept":"M5-1-u1-C3","difficulty":2,"kind":"mc","stem":"96 ÷ 8 × 3 ÷ 4를 계산하면 얼마인가요?","options":[{"t":"9","correct":true},{"t":"1","mis":"M5-1-u1-X02"},{"t":"19","mis":"M5-1-u1-X10"},{"t":"11","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 96 ÷ 8 = 12 → ② 12 × 3 = 36 → ③ 36 ÷ 4 = 9예요.","그래서 96 ÷ 8 × 3 ÷ 4 = 9예요."],"variant_rule":{"alt":[{"stem":"84 ÷ 7 × 5 ÷ 6을 계산하면 얼마인가요?","options":[{"t":"10","correct":true},{"t":"20","mis":"M5-1-u1-X10"},{"t":"12","mis":"M5-1-u1-X10"},{"t":"8","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 84 ÷ 7 = 12 → ② 12 × 5 = 60 → ③ 60 ÷ 6 = 10이에요.","그래서 84 ÷ 7 × 5 ÷ 6 = 10이에요."]},{"stem":"72 ÷ 9 × 6 ÷ 4를 계산하면 얼마인가요?","options":[{"t":"12","correct":true},{"t":"22","mis":"M5-1-u1-X10"},{"t":"2","mis":"M5-1-u1-X10"},{"t":"14","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 72 ÷ 9 = 8 → ② 8 × 6 = 48 → ③ 48 ÷ 4 = 12예요.","그래서 72 ÷ 9 × 6 ÷ 4 = 12예요."]}]}}'::jsonb),
('g5_1_math_u1_L03_challenge#2','math',5,1,'u1','L03','g5_1_math_u1_L03_challenge','lesson_challenge','M5-1-u1-C3',2,'mc','auto','「곱셈이 나눗셈보다 먼저야.」라는 말을 바르게 판단한 것은 어느 것인가요?',ARRAY['M5-1-u1-X05','M5-1-u1-X02']::text[],false,'{"seq":2,"concept":"M5-1-u1-C3","difficulty":2,"kind":"mc","stem":"「곱셈이 나눗셈보다 먼저야.」라는 말을 바르게 판단한 것은 어느 것인가요?","options":[{"t":"틀리다 · 곱셈과 나눗셈은 앞에서부터 차례로 한다","correct":true},{"t":"맞다 · 곱셈이 언제나 먼저다","mis":"M5-1-u1-X05"},{"t":"맞다 · 곱셈이 뒤에 있어도 먼저 한다","mis":"M5-1-u1-X02"},{"t":"틀리다 · 나눗셈이 언제나 먼저다","mis":"M5-1-u1-X05"}],"explanation":["곱셈과 나눗셈은 서로를 되돌리는 계산이에요.","그래서 같은 자리 — 어느 쪽이 먼저가 아니에요.","둘만 섞이면 앞에서부터 차례로 계산해요."]}'::jsonb),
('g5_1_math_u1_L03_challenge#3','math',5,1,'u1','L03','g5_1_math_u1_L03_challenge','lesson_challenge','M5-1-u1-C3',3,'mc','auto','□ ÷ 6 × 4 = 32에서 □에 알맞은 수는 얼마인가요?',ARRAY['M5-1-u1-X13','M5-1-u1-X02']::text[],true,'{"seq":3,"concept":"M5-1-u1-C3","difficulty":3,"kind":"mc","stem":"□ ÷ 6 × 4 = 32에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"48","correct":true},{"t":"8","mis":"M5-1-u1-X13"},{"t":"192","mis":"M5-1-u1-X13"},{"t":"12","mis":"M5-1-u1-X02"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 32가 되어야 해요.","거꾸로 되돌리면 □ = 48이에요.","확인: 48 ÷ 6 × 4 → ① 48 ÷ 6 = 8 → ② 8 × 4 = 32"],"variant_rule":{"alt":[{"stem":"□ ÷ 5 × 3 = 27에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"45","correct":true},{"t":"9","mis":"M5-1-u1-X13"},{"t":"135","mis":"M5-1-u1-X13"},{"t":"15","mis":"M5-1-u1-X02"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 27이 되어야 해요.","거꾸로 되돌리면 □ = 45예요.","확인: 45 ÷ 5 × 3 → ① 45 ÷ 5 = 9 → ② 9 × 3 = 27"]}]}}'::jsonb),
('g5_1_math_u1_L03_challenge#4','math',5,1,'u1','L03','g5_1_math_u1_L03_challenge','lesson_challenge','M5-1-u1-C3',3,'mc','auto','다음 중 계산 결과가 가장 큰 것은 어느 것인가요?',ARRAY['M5-1-u1-X14']::text[],false,'{"seq":4,"concept":"M5-1-u1-C3","difficulty":3,"kind":"mc","stem":"다음 중 계산 결과가 가장 큰 것은 어느 것인가요?","options":[{"t":"72 ÷ 6 × 3","correct":true},{"t":"72 ÷ (6 × 3)","mis":"M5-1-u1-X14"},{"t":"72 ÷ 3 ÷ 6","mis":"M5-1-u1-X14"},{"t":"72 ÷ 6 ÷ 3","mis":"M5-1-u1-X14"}],"explanation":["식마다 앞에서부터(또는 ( ) 먼저) 셈해요.","72 ÷ 6 × 3 = 36 · 72 ÷ (6 × 3) = 4 · 72 ÷ 3 ÷ 6 = 4 · 72 ÷ 6 ÷ 3 = 4.","가장 큰 것은 72 ÷ 6 × 3 = 36이에요."]}'::jsonb),
('g5_1_math_u1_L03_challenge#5','math',5,1,'u1','L03','g5_1_math_u1_L03_challenge','lesson_challenge','M5-1-u1-C3',3,'mc','auto','연필 한 타는 12자루예요. 연필 5타를 학생 6명에게 똑같이 나누어 주면 한 명은 몇 자루를 받나요?',ARRAY['M5-1-u1-X02','M5-1-u1-X09']::text[],true,'{"seq":5,"concept":"M5-1-u1-C3","difficulty":3,"kind":"mc","stem":"연필 한 타는 12자루예요. 연필 5타를 학생 6명에게 똑같이 나누어 주면 한 명은 몇 자루를 받나요?","options":[{"t":"10자루","correct":true},{"t":"2자루","mis":"M5-1-u1-X02"},{"t":"72자루","mis":"M5-1-u1-X09"},{"t":"60자루","mis":"M5-1-u1-X09"}],"explanation":["연필은 모두 12 × 5자루예요.","그것을 6명에게 나누니 12 × 5 ÷ 6이에요.","앞에서부터 — 12 × 5 = 60, 60 ÷ 6 = 10자루예요."],"variant_rule":{"alt":[{"stem":"달걀 한 판은 30개예요. 달걀 2판을 5집에 똑같이 나누어 주면 한 집은 몇 개를 받나요?","options":[{"t":"12개","correct":true},{"t":"3개","mis":"M5-1-u1-X02"},{"t":"150개","mis":"M5-1-u1-X09"},{"t":"60개","mis":"M5-1-u1-X09"}],"explanation":["달걀은 모두 30 × 2개예요.","5집에 나누니 30 × 2 ÷ 5예요.","30 × 2 = 60, 60 ÷ 5 = 12개예요."]}]}}'::jsonb),
('g5_1_math_u1_L03_challenge#6','math',5,1,'u1','L03','g5_1_math_u1_L03_challenge','lesson_challenge','M5-1-u1-C3',3,'error','auto','「24 ÷ 4 × 3」을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u1-X02','M5-1-u1-X14']::text[],false,'{"seq":6,"concept":"M5-1-u1-C3","difficulty":3,"kind":"error","stem":"「24 ÷ 4 × 3」을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「4 × 3 = 12를 먼저 해서 24 ÷ 12 = 2야.」","correct":true,"mis_target":"M5-1-u1-X02"},{"t":"민준 — 「한 접시에 6개씩, 3접시면 18개야.」","mis":"M5-1-u1-X14"},{"t":"하린 — 「앞에서부터 24 ÷ 4 = 6, 6 × 3 = 18이야.」","mis":"M5-1-u1-X14"}],"explanation":["곱셈과 나눗셈은 앞에서부터 계산해요.","24 ÷ 4 = 6, 6 × 3 = 18이에요.","수아는 곱셈을 먼저 해서 2가 나왔는데, 쿠키가 접시 하나에도 못 미치니 이상해요."]}'::jsonb),
('g5_1_math_u1_L03_challenge#7','math',5,1,'u1','L03','g5_1_math_u1_L03_challenge','lesson_challenge','M5-1-u1-C3',3,'sa','auto','81 ÷ 9 × 6 ÷ 2를 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-1-u1-C3","difficulty":3,"kind":"sa","stem":"81 ÷ 9 × 6 ÷ 2를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 81 ÷ 9 = 9 → ② 9 × 6 = 54 → ③ 54 ÷ 2 = 27이에요.","그래서 81 ÷ 9 × 6 ÷ 2 = 27이에요."],"variant_rule":{"alt":[{"stem":"64 ÷ 8 × 9 ÷ 3을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 64 ÷ 8 = 8 → ② 8 × 9 = 72 → ③ 72 ÷ 3 = 24예요.","그래서 64 ÷ 8 × 9 ÷ 3 = 24예요."]},{"stem":"90 ÷ 6 × 4 ÷ 5를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 90 ÷ 6 = 15 → ② 15 × 4 = 60 → ③ 60 ÷ 5 = 12예요.","그래서 90 ÷ 6 × 4 ÷ 5 = 12예요."]}]}}'::jsonb),
('g5_1_math_u1_L03_challenge#8','math',5,1,'u1','L03','g5_1_math_u1_L03_challenge','lesson_challenge','M5-1-u1-C3',4,'essay','teacher','쿠키 24개를 접시 4개에 똑같이 나누어 담고 그중 3접시를 가져가요. 24 ÷ 4 × 3을 곱셈부터 계산하면 왜 이야기와 맞지 않는지 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"M5-1-u1-C3","difficulty":4,"kind":"essay","stem":"쿠키 24개를 접시 4개에 똑같이 나누어 담고 그중 3접시를 가져가요. 24 ÷ 4 × 3을 곱셈부터 계산하면 왜 이야기와 맞지 않는지 설명하세요.","answer_guide":{"answer":"예: 곱셈부터 하면 4 × 3 = 12, 24 ÷ 12 = 2로 쿠키가 2개뿐이 되어, 한 접시에 담긴 6개보다도 적다. 실제로는 한 접시에 24 ÷ 4 = 6개를 먼저 구하고 3접시를 모아 6 × 3 = 18개이다. 나눈 다음에 모았으니 앞에서부터 계산해야 한다.","scoring_points":["곱셈부터 하면 2가 나옴을 보였는가","앞에서부터 계산해 18을 구했는가","나눈 뒤 모은 차례 때문이라는 까닭을 썼는가"]},"explanation":["곱셈부터 하면 24 ÷ 12 = 2예요.","앞에서부터 하면 6 × 3 = 18이에요.","나눈 다음에 모았으니 앞에서부터가 맞아요."]}'::jsonb),
('g5_1_math_u1_L03_challenge#9','math',5,1,'u1','L03','g5_1_math_u1_L03_challenge','lesson_challenge','M5-1-u1-C3',4,'essay','teacher','7 × 8 ÷ 4를 앞에서부터 계산한 답과 8 ÷ 4를 먼저 계산한 답을 각각 구하고, 이 식에서 두 답이 같은지 다른지 쓰세요. 그래도 계산 순서는 어떻게 약속되어 있는지 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u1-C3","difficulty":4,"kind":"essay","stem":"7 × 8 ÷ 4를 앞에서부터 계산한 답과 8 ÷ 4를 먼저 계산한 답을 각각 구하고, 이 식에서 두 답이 같은지 다른지 쓰세요. 그래도 계산 순서는 어떻게 약속되어 있는지 함께 쓰세요.","answer_guide":{"answer":"예: 앞에서부터 7 × 8 = 56, 56 ÷ 4 = 14이다. 8 ÷ 4 = 2를 먼저 하면 7 × 2 = 14로 이 식에서는 답이 같다. 그러나 24 ÷ 4 × 3처럼 바꾸면 답이 달라지는 식이 있으므로 곱셈과 나눗셈은 앞에서부터 계산하기로 약속되어 있다.","scoring_points":["앞에서부터 계산해 14를 구했는가","8 ÷ 4를 먼저 해도 14임을 보였는가","그래도 앞에서부터 계산하는 약속을 밝혔는가"]},"explanation":["앞에서부터 7 × 8 ÷ 4 = 56 ÷ 4 = 14예요.","이 식은 8 ÷ 4부터 해도 14예요.","하지만 약속은 언제나 앞에서부터예요."]}'::jsonb),
('g5_1_math_u1_L03_challenge#10','math',5,1,'u1','L03','g5_1_math_u1_L03_challenge','lesson_challenge','M5-1-u1-C3',4,'mc','auto','어떤 수를 3으로 나눈 다음 8을 곱했더니 56이 되었어요. 어떤 수는 얼마인가요?',ARRAY['M5-1-u1-X13','M5-1-u1-X02']::text[],true,'{"seq":10,"concept":"M5-1-u1-C3","difficulty":4,"kind":"mc","stem":"어떤 수를 3으로 나눈 다음 8을 곱했더니 56이 되었어요. 어떤 수는 얼마인가요?","options":[{"t":"21","correct":true},{"t":"7","mis":"M5-1-u1-X13"},{"t":"168","mis":"M5-1-u1-X13"},{"t":"18","mis":"M5-1-u1-X02"}],"explanation":["□ ÷ 3 × 8 = 56이에요.","거꾸로 되돌리면 56 ÷ 8 = 7, 7 × 3 = 21이에요.","확인: 21 ÷ 3 × 8 = 7 × 8 = 56이에요."],"variant_rule":{"alt":[{"stem":"어떤 수를 4로 나눈 다음 6을 곱했더니 54가 되었어요. 어떤 수는 얼마인가요?","options":[{"t":"36","correct":true},{"t":"9","mis":"M5-1-u1-X13"},{"t":"216","mis":"M5-1-u1-X13"},{"t":"24","mis":"M5-1-u1-X02"}],"explanation":["□ ÷ 4 × 6 = 54예요.","거꾸로 54 ÷ 6 = 9, 9 × 4 = 36이에요.","확인: 36 ÷ 4 × 6 = 9 × 6 = 54예요."]}]}}'::jsonb),
('g5_1_math_u1_L04_basic#1','math',5,1,'u1','L04','g5_1_math_u1_L04_basic','lesson_basic','M5-1-u1-C4',1,'mc','auto','1000 − 350 × 2에서 가장 먼저 계산해야 할 것은 어느 것인가요?',ARRAY['M5-1-u1-X03']::text[],true,'{"seq":1,"concept":"M5-1-u1-C4","difficulty":1,"kind":"mc","stem":"1000 − 350 × 2에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"350 × 2","correct":true},{"t":"1000 − 350","mis":"M5-1-u1-X03"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X03"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","그래서 가장 먼저 계산할 것은 350 × 2예요.","① 350 × 2 = 700 → ② 1000 − 700 = 300이에요."],"variant_rule":{"alt":[{"stem":"5 + 3 × 4에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"3 × 4","correct":true},{"t":"5 + 3","mis":"M5-1-u1-X03"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X03"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","가장 먼저 계산할 것은 3 × 4예요.","① 3 × 4 = 12 → ② 5 + 12 = 17이에요."]},{"stem":"20 − 3 × 4에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"3 × 4","correct":true},{"t":"20 − 3","mis":"M5-1-u1-X03"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X03"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","가장 먼저 계산할 것은 3 × 4예요.","① 3 × 4 = 12 → ② 20 − 12 = 8이에요."]}]}}'::jsonb),
('g5_1_math_u1_L04_basic#2','math',5,1,'u1','L04','g5_1_math_u1_L04_basic','lesson_basic','M5-1-u1-C4',1,'mc','auto','지호는 1000원을 들고 문구점에 가서 350원짜리 지우개 2개를 샀어요. 남은 돈은 얼마인가요?',ARRAY['M5-1-u1-X03','M5-1-u1-X09']::text[],true,'{"seq":2,"concept":"M5-1-u1-C4","difficulty":1,"kind":"mc","stem":"지호는 1000원을 들고 문구점에 가서 350원짜리 지우개 2개를 샀어요. 남은 돈은 얼마인가요?","options":[{"t":"300원","correct":true},{"t":"1300원","mis":"M5-1-u1-X03"},{"t":"650원","mis":"M5-1-u1-X09"},{"t":"1700원","mis":"M5-1-u1-X09"}],"explanation":["남은 돈은 1000 − 350 × 2예요.","곱셈을 먼저 — 350 × 2 = 700, 1000 − 700 = 300.","앞에서부터 하면 1300원으로 가진 돈보다 많아져 이상해요."],"variant_rule":{"alt":[{"stem":"하은이는 2000원을 들고 가서 450원짜리 풀 3개를 샀어요. 남은 돈은 얼마인가요?","options":[{"t":"650원","correct":true},{"t":"4650원","mis":"M5-1-u1-X03"},{"t":"1550원","mis":"M5-1-u1-X09"},{"t":"3350원","mis":"M5-1-u1-X09"}],"explanation":["남은 돈은 2000 − 450 × 3이에요.","곱셈을 먼저 — 450 × 3 = 1350, 2000 − 1350 = 650.","650원이에요."]}]}}'::jsonb),
('g5_1_math_u1_L04_basic#3','math',5,1,'u1','L04','g5_1_math_u1_L04_basic','lesson_basic','M5-1-u1-C4',1,'sa','auto','7 + 6 × 5를 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-1-u1-C4","difficulty":1,"kind":"sa","stem":"7 + 6 × 5를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["37"],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 6 × 5 = 30 → ② 7 + 30 = 37이에요.","그래서 7 + 6 × 5 = 37이에요."],"variant_rule":{"alt":[{"stem":"9 + 4 × 8을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["41"],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 4 × 8 = 32 → ② 9 + 32 = 41이에요.","그래서 9 + 4 × 8 = 41이에요."]},{"stem":"6 + 7 × 3을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 7 × 3 = 21 → ② 6 + 21 = 27이에요.","그래서 6 + 7 × 3 = 27이에요."]}]}}'::jsonb),
('g5_1_math_u1_L04_basic#4','math',5,1,'u1','L04','g5_1_math_u1_L04_basic','lesson_basic','M5-1-u1-C4',1,'mc','auto','50 − 4 × 6을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X03','M5-1-u1-X10']::text[],true,'{"seq":4,"concept":"M5-1-u1-C4","difficulty":1,"kind":"mc","stem":"50 − 4 × 6을 계산하면 얼마인가요?","options":[{"t":"26","correct":true},{"t":"276","mis":"M5-1-u1-X03"},{"t":"36","mis":"M5-1-u1-X10"},{"t":"16","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 4 × 6 = 24 → ② 50 − 24 = 26이에요.","그래서 50 − 4 × 6 = 26이에요."],"variant_rule":{"alt":[{"stem":"80 − 9 × 7을 계산하면 얼마인가요?","options":[{"t":"17","correct":true},{"t":"497","mis":"M5-1-u1-X03"},{"t":"27","mis":"M5-1-u1-X10"},{"t":"7","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 9 × 7 = 63 → ② 80 − 63 = 17이에요.","그래서 80 − 9 × 7 = 17이에요."]},{"stem":"60 − 8 × 5를 계산하면 얼마인가요?","options":[{"t":"20","correct":true},{"t":"260","mis":"M5-1-u1-X03"},{"t":"30","mis":"M5-1-u1-X10"},{"t":"10","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 8 × 5 = 40 → ② 60 − 40 = 20이에요.","그래서 60 − 8 × 5 = 20이에요."]}]}}'::jsonb),
('g5_1_math_u1_L04_basic#5','math',5,1,'u1','L04','g5_1_math_u1_L04_basic','lesson_basic','M5-1-u1-C4',2,'error','auto','서아는 5 + 3 × 4를 계산해 32라고 답했어요. 서아가 잘못한 것은 무엇인가요?',ARRAY['M5-1-u1-X03','M5-1-u1-X10','M5-1-u1-X14']::text[],true,'{"seq":5,"concept":"M5-1-u1-C4","difficulty":2,"kind":"error","stem":"서아는 5 + 3 × 4를 계산해 32라고 답했어요. 서아가 잘못한 것은 무엇인가요?","options":[{"t":"앞의 5 + 3을 먼저 했다","correct":true,"mis_target":"M5-1-u1-X03"},{"t":"3 × 4를 잘못 곱했다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["덧셈에 곱셈이 섞이면 곱셈을 먼저 해요.","3 × 4 = 12, 5 + 12 = 17이 맞아요.","서아는 5 + 3 = 8을 먼저 해서 8 × 4 = 32가 나왔어요."],"variant_rule":{"alt":[{"stem":"도현이는 9 + 2 × 6을 계산해 66이라고 답했어요. 도현이가 잘못한 것은 무엇인가요?","options":[{"t":"앞의 9 + 2를 먼저 했다","correct":true,"mis_target":"M5-1-u1-X03"},{"t":"2 × 6을 잘못 곱했다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["곱셈을 먼저 해요.","2 × 6 = 12, 9 + 12 = 21이 맞아요.","도현이는 9 + 2 = 11을 먼저 해서 11 × 6 = 66이 나왔어요."]}]}}'::jsonb),
('g5_1_math_u1_L04_basic#6','math',5,1,'u1','L04','g5_1_math_u1_L04_basic','lesson_basic','M5-1-u1-C4',2,'sa','auto','4개들이 사탕 6봉지가 있었어요. 그중 9개를 먹었다면 남은 사탕은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u1-C4","difficulty":2,"kind":"sa","stem":"4개들이 사탕 6봉지가 있었어요. 그중 9개를 먹었다면 남은 사탕은 몇 개인가요? 숫자로 쓰세요.","answer":["15","15개"],"explanation":["사탕은 모두 4 × 6개, 먹은 것은 9개 — 4 × 6 − 9.","곱셈을 먼저 — 4 × 6 = 24, 24 − 9 = 15.","남은 사탕은 15개예요."],"variant_rule":{"alt":[{"stem":"5개들이 귤 7봉지가 있었어요. 그중 8개를 먹었다면 남은 귤은 몇 개인가요? 숫자로 쓰세요.","answer":["27","27개"],"explanation":["5 × 7 − 8이에요.","5 × 7 = 35, 35 − 8 = 27.","27개예요."]}]}}'::jsonb),
('g5_1_math_u1_L04_basic#7','math',5,1,'u1','L04','g5_1_math_u1_L04_basic','lesson_basic','M5-1-u1-C4',2,'ox','auto','「350 × 2」는 350원이 2개라는 하나의 값이라서, 1000 − 350 × 2에서는 곱셈을 먼저 해요.',ARRAY['M5-1-u1-X03']::text[],false,'{"seq":7,"concept":"M5-1-u1-C4","difficulty":2,"kind":"ox","stem":"「350 × 2」는 350원이 2개라는 하나의 값이라서, 1000 − 350 × 2에서는 곱셈을 먼저 해요.","answer":"O","reason_options":[{"t":"곱셈 부분이 이미 하나의 양(덩어리)이라 먼저 구해 두어야 해서","correct":true},{"t":"곱셈이 뺄셈보다 힘이 세서","mis":"M5-1-u1-X03"}],"mis":"M5-1-u1-X03","explanation":["350 × 2는 지우개 2개의 값 — 700원짜리 하나인 셈이에요.","덩어리를 먼저 만들고 그다음 빼요.","곱셈이 힘이 세서가 아니라 하나의 양이기 때문이에요."]}'::jsonb),
('g5_1_math_u1_L04_basic#8','math',5,1,'u1','L04','g5_1_math_u1_L04_basic','lesson_basic','M5-1-u1-C4',2,'match','auto','계산식과 계산 결과를 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u1-C4","difficulty":2,"kind":"match","stem":"계산식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"8 + 3 × 7","r":"29"},{"l":"30 − 4 × 5","r":"10"},{"l":"6 × 4 + 9","r":"33"}],"mis":"M5-1-u1-X03","explanation":["식마다 계산 순서를 지켜 셈해요.","8 + 3 × 7 = 29 · 30 − 4 × 5 = 10 · 6 × 4 + 9 = 33","곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 계산식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"5 + 6 × 3","r":"23"},{"l":"40 − 7 × 4","r":"12"},{"l":"9 × 3 − 8","r":"19"}],"explanation":["식마다 계산 순서를 지켜 셈해요.","5 + 6 × 3 = 23 · 40 − 7 × 4 = 12 · 9 × 3 − 8 = 19","곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요."]}]}}'::jsonb),
('g5_1_math_u1_L04_basic#9','math',5,1,'u1','L04','g5_1_math_u1_L04_basic','lesson_basic','M5-1-u1-C4',2,'mc','auto','45 − 3 × 8 + 6을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X03','M5-1-u1-X01','M5-1-u1-X10']::text[],true,'{"seq":9,"concept":"M5-1-u1-C4","difficulty":2,"kind":"mc","stem":"45 − 3 × 8 + 6을 계산하면 얼마인가요?","options":[{"t":"27","correct":true},{"t":"342","mis":"M5-1-u1-X03"},{"t":"15","mis":"M5-1-u1-X01"},{"t":"37","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 3 × 8 = 24 → ② 45 − 24 = 21 → ③ 21 + 6 = 27이에요.","그래서 45 − 3 × 8 + 6 = 27이에요."],"variant_rule":{"alt":[{"stem":"52 + 4 × 7 − 30을 계산하면 얼마인가요?","options":[{"t":"50","correct":true},{"t":"362","mis":"M5-1-u1-X03"},{"t":"60","mis":"M5-1-u1-X10"},{"t":"40","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 4 × 7 = 28 → ② 52 + 28 = 80 → ③ 80 − 30 = 50이에요.","그래서 52 + 4 × 7 − 30 = 50이에요."]},{"stem":"38 − 5 × 6 + 12를 계산하면 얼마인가요?","options":[{"t":"20","correct":true},{"t":"210","mis":"M5-1-u1-X03"},{"t":"30","mis":"M5-1-u1-X10"},{"t":"10","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 5 × 6 = 30 → ② 38 − 30 = 8 → ③ 8 + 12 = 20이에요.","그래서 38 − 5 × 6 + 12 = 20이에요."]}]}}'::jsonb),
('g5_1_math_u1_L04_basic#10','math',5,1,'u1','L04','g5_1_math_u1_L04_basic','lesson_basic','M5-1-u1-C4',3,'mc','auto','20 − 3 × 4와 (20 − 3) × 4의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],true,'{"seq":10,"concept":"M5-1-u1-C4","difficulty":3,"kind":"mc","stem":"20 − 3 × 4와 (20 − 3) × 4의 계산 결과의 차는 얼마인가요?","options":[{"t":"60","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"8","mis":"M5-1-u1-X14"},{"t":"68","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","20 − 3 × 4 = 8 · (20 − 3) × 4 = 68","두 결과의 차는 68 − 8 = 60이에요."],"variant_rule":{"alt":[{"stem":"30 − 2 × 9와 (30 − 2) × 9의 계산 결과의 차는 얼마인가요?","options":[{"t":"240","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"12","mis":"M5-1-u1-X14"},{"t":"252","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","30 − 2 × 9 = 12 · (30 − 2) × 9 = 252","두 결과의 차는 252 − 12 = 240이에요."]}]}}'::jsonb),
('g5_1_math_u1_L04_challenge#1','math',5,1,'u1','L04','g5_1_math_u1_L04_challenge','lesson_challenge','M5-1-u1-C4',2,'mc','auto','64 − 7 × 8 + 15를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X03','M5-1-u1-X10']::text[],true,'{"seq":1,"concept":"M5-1-u1-C4","difficulty":2,"kind":"mc","stem":"64 − 7 × 8 + 15를 계산하면 얼마인가요?","options":[{"t":"23","correct":true},{"t":"471","mis":"M5-1-u1-X03"},{"t":"33","mis":"M5-1-u1-X10"},{"t":"13","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 7 × 8 = 56 → ② 64 − 56 = 8 → ③ 8 + 15 = 23이에요.","그래서 64 − 7 × 8 + 15 = 23이에요."],"variant_rule":{"alt":[{"stem":"90 − 6 × 9 + 28을 계산하면 얼마인가요?","options":[{"t":"64","correct":true},{"t":"784","mis":"M5-1-u1-X03"},{"t":"8","mis":"M5-1-u1-X01"},{"t":"74","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 6 × 9 = 54 → ② 90 − 54 = 36 → ③ 36 + 28 = 64예요.","그래서 90 − 6 × 9 + 28 = 64예요."]},{"stem":"75 + 8 × 4 − 46을 계산하면 얼마인가요?","options":[{"t":"61","correct":true},{"t":"286","mis":"M5-1-u1-X03"},{"t":"71","mis":"M5-1-u1-X10"},{"t":"51","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 8 × 4 = 32 → ② 75 + 32 = 107 → ③ 107 − 46 = 61이에요.","그래서 75 + 8 × 4 − 46 = 61이에요."]}]}}'::jsonb),
('g5_1_math_u1_L04_challenge#2','math',5,1,'u1','L04','g5_1_math_u1_L04_challenge','lesson_challenge','M5-1-u1-C4',2,'mc','auto','「섞여 있는 식은 무조건 앞에서부터야.」라는 말을 바르게 판단한 것은 어느 것인가요?',ARRAY['M5-1-u1-X03','M5-1-u1-X08']::text[],false,'{"seq":2,"concept":"M5-1-u1-C4","difficulty":2,"kind":"mc","stem":"「섞여 있는 식은 무조건 앞에서부터야.」라는 말을 바르게 판단한 것은 어느 것인가요?","options":[{"t":"틀리다 · 곱셈이 있으면 곱셈이 먼저다","correct":true},{"t":"맞다 · 언제나 앞에서부터 한다","mis":"M5-1-u1-X03"},{"t":"맞다 · 곱셈도 앞에 있으면 나중이다","mis":"M5-1-u1-X03"},{"t":"틀리다 · 뺄셈을 먼저 해야 한다","mis":"M5-1-u1-X08"}],"explanation":["덧셈·뺄셈만, 곱셈·나눗셈만 섞였을 때는 앞에서부터예요.","덧셈·뺄셈에 곱셈이 섞이면 곱셈이 먼저예요.","그래서 「무조건 앞에서부터」는 틀려요."]}'::jsonb),
('g5_1_math_u1_L04_challenge#3','math',5,1,'u1','L04','g5_1_math_u1_L04_challenge','lesson_challenge','M5-1-u1-C4',3,'mc','auto','50 − □ × 3 = 26에서 □에 알맞은 수는 얼마인가요?',ARRAY['M5-1-u1-X13','M5-1-u1-X03']::text[],true,'{"seq":3,"concept":"M5-1-u1-C4","difficulty":3,"kind":"mc","stem":"50 − □ × 3 = 26에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"8","correct":true},{"t":"24","mis":"M5-1-u1-X13"},{"t":"12","mis":"M5-1-u1-X03"},{"t":"6","mis":"M5-1-u1-X13"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 26이 되어야 해요.","거꾸로 되돌리면 □ = 8이에요.","확인: 50 − 8 × 3 → ① 8 × 3 = 24 → ② 50 − 24 = 26"],"variant_rule":{"alt":[{"stem":"60 − □ × 4 = 32에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"7","correct":true},{"t":"28","mis":"M5-1-u1-X13"},{"t":"8","mis":"M5-1-u1-X03"},{"t":"23","mis":"M5-1-u1-X13"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 32가 되어야 해요.","거꾸로 되돌리면 □ = 7이에요.","확인: 60 − 7 × 4 → ① 7 × 4 = 28 → ② 60 − 28 = 32"]}]}}'::jsonb),
('g5_1_math_u1_L04_challenge#4','math',5,1,'u1','L04','g5_1_math_u1_L04_challenge','lesson_challenge','M5-1-u1-C4',3,'mc','auto','연필 한 자루는 600원, 지우개 한 개는 400원이에요. 연필 3자루와 지우개 2개를 사고 5000원을 냈어요. 거스름돈을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M5-1-u1-X09','M5-1-u1-X03']::text[],false,'{"seq":4,"concept":"M5-1-u1-C4","difficulty":3,"kind":"mc","stem":"연필 한 자루는 600원, 지우개 한 개는 400원이에요. 연필 3자루와 지우개 2개를 사고 5000원을 냈어요. 거스름돈을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"5000 − 600 × 3 − 400 × 2","correct":true},{"t":"5000 − 600 × 3 + 400 × 2","mis":"M5-1-u1-X09"},{"t":"5000 − 600 + 400 × 3 × 2","mis":"M5-1-u1-X09"},{"t":"(5000 − 600) × 3 − 400 × 2","mis":"M5-1-u1-X03"}],"explanation":["연필 값은 600 × 3, 지우개 값은 400 × 2예요.","두 값을 모두 5000원에서 빼요.","5000 − 600 × 3 − 400 × 2 = 5000 − 1800 − 800 = 2400원이에요."]}'::jsonb),
('g5_1_math_u1_L04_challenge#5','math',5,1,'u1','L04','g5_1_math_u1_L04_challenge','lesson_challenge','M5-1-u1-C4',3,'mc','auto','5000 − 600 × 3 − 400 × 2를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X10','M5-1-u1-X03']::text[],false,'{"seq":5,"concept":"M5-1-u1-C4","difficulty":3,"kind":"mc","stem":"5000 − 600 × 3 − 400 × 2를 계산하면 얼마인가요?","options":[{"t":"2400","correct":true},{"t":"3200","mis":"M5-1-u1-X10"},{"t":"8400","mis":"M5-1-u1-X03"},{"t":"4000","mis":"M5-1-u1-X10"}],"explanation":["곱셈 둘을 먼저 — 600 × 3 = 1800, 400 × 2 = 800.","그다음 앞에서부터 — 5000 − 1800 = 3200, 3200 − 800 = 2400.","거스름돈은 2400원이에요."]}'::jsonb),
('g5_1_math_u1_L04_challenge#6','math',5,1,'u1','L04','g5_1_math_u1_L04_challenge','lesson_challenge','M5-1-u1-C4',3,'error','auto','「7 + 6 × 5」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u1-X03','M5-1-u1-X14']::text[],false,'{"seq":6,"concept":"M5-1-u1-C4","difficulty":3,"kind":"error","stem":"「7 + 6 × 5」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안 — 「7 + 6 = 13을 먼저 하고 5를 곱하면 65야.」","correct":true,"mis_target":"M5-1-u1-X03"},{"t":"유나 — 「6 × 5는 하나의 덩어리라 먼저 해.」","mis":"M5-1-u1-X14"},{"t":"건우 — 「6 × 5 = 30, 7 + 30 = 37이야.」","mis":"M5-1-u1-X14"}],"explanation":["덧셈에 곱셈이 섞이면 곱셈을 먼저 해요.","6 × 5 = 30, 7 + 30 = 37이에요.","지안이는 앞에서부터 해서 65가 나왔어요."]}'::jsonb),
('g5_1_math_u1_L04_challenge#7','math',5,1,'u1','L04','g5_1_math_u1_L04_challenge','lesson_challenge','M5-1-u1-C4',3,'mc','auto','8 + 4 × 6과 (8 + 4) × 6의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],true,'{"seq":7,"concept":"M5-1-u1-C4","difficulty":3,"kind":"mc","stem":"8 + 4 × 6과 (8 + 4) × 6의 계산 결과의 차는 얼마인가요?","options":[{"t":"40","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"32","mis":"M5-1-u1-X14"},{"t":"72","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","8 + 4 × 6 = 32 · (8 + 4) × 6 = 72","두 결과의 차는 72 − 32 = 40이에요."],"variant_rule":{"alt":[{"stem":"9 + 3 × 7과 (9 + 3) × 7의 계산 결과의 차는 얼마인가요?","options":[{"t":"54","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"30","mis":"M5-1-u1-X14"},{"t":"84","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","9 + 3 × 7 = 30 · (9 + 3) × 7 = 84","두 결과의 차는 84 − 30 = 54예요."]}]}}'::jsonb),
('g5_1_math_u1_L04_challenge#8','math',5,1,'u1','L04','g5_1_math_u1_L04_challenge','lesson_challenge','M5-1-u1-C4',4,'essay','teacher','1000 − 350 × 2를 앞에서부터 계산하면 1300이 나와요. 지우개 이야기(1000원으로 350원짜리 지우개 2개를 삼)를 들어 이 답이 왜 이상한지, 바른 계산은 무엇인지 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"M5-1-u1-C4","difficulty":4,"kind":"essay","stem":"1000 − 350 × 2를 앞에서부터 계산하면 1300이 나와요. 지우개 이야기(1000원으로 350원짜리 지우개 2개를 삼)를 들어 이 답이 왜 이상한지, 바른 계산은 무엇인지 설명하세요.","answer_guide":{"answer":"예: 앞에서부터 하면 1000 − 350 = 650, 650 × 2 = 1300으로 가진 돈 1000원보다 많아져 이상하다. 350 × 2는 지우개 2개 값이라는 하나의 양이므로 먼저 구한다. 350 × 2 = 700, 1000 − 700 = 300원이 남는다.","scoring_points":["1300이 가진 돈보다 많아 이상함을 썼는가","350 × 2가 하나의 양(덩어리)임을 설명했는가","바른 답 300원을 구했는가"]},"explanation":["앞에서부터 하면 가진 돈보다 많은 1300이 나와요.","350 × 2는 지우개 값이라는 하나의 양이에요.","1000 − 700 = 300원이 맞아요."]}'::jsonb),
('g5_1_math_u1_L04_challenge#9','math',5,1,'u1','L04','g5_1_math_u1_L04_challenge','lesson_challenge','M5-1-u1-C4',4,'essay','teacher','「사과 3개씩 5봉지에서 4개를 먹었다」를 식으로 나타내 계산하고, 곱셈을 먼저 하는 까닭을 이 상황에 맞게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u1-C4","difficulty":4,"kind":"essay","stem":"「사과 3개씩 5봉지에서 4개를 먹었다」를 식으로 나타내 계산하고, 곱셈을 먼저 하는 까닭을 이 상황에 맞게 쓰세요.","answer_guide":{"answer":"예: 3 × 5 − 4 = 15 − 4 = 11개. 3 × 5는 봉지에 든 사과 전체라는 하나의 양이어서, 그 양을 먼저 구한 다음 먹은 4개를 빼야 한다.","scoring_points":["3 × 5 − 4로 식을 세웠는가","11개를 구했는가","곱셈 부분이 전체 양(덩어리)이라는 까닭을 썼는가"]},"explanation":["식은 3 × 5 − 4예요.","3 × 5 = 15, 15 − 4 = 11개예요.","3 × 5는 사과 전체라는 하나의 양이라 먼저 구해요."]}'::jsonb),
('g5_1_math_u1_L04_challenge#10','math',5,1,'u1','L04','g5_1_math_u1_L04_challenge','lesson_challenge','M5-1-u1-C4',4,'mc','auto','어떤 수에 6을 곱한 다음 25를 더해야 할 것을 잘못하여 어떤 수에 25를 더한 다음 6을 곱했더니 192가 되었어요. 바르게 계산하면 얼마인가요?',ARRAY['M5-1-u1-X14','M5-1-u1-X13']::text[],false,'{"seq":10,"concept":"M5-1-u1-C4","difficulty":4,"kind":"mc","stem":"어떤 수에 6을 곱한 다음 25를 더해야 할 것을 잘못하여 어떤 수에 25를 더한 다음 6을 곱했더니 192가 되었어요. 바르게 계산하면 얼마인가요?","options":[{"t":"67","correct":true},{"t":"192","mis":"M5-1-u1-X14"},{"t":"42","mis":"M5-1-u1-X13"},{"t":"7","mis":"M5-1-u1-X13"}],"explanation":["잘못 계산한 식은 (□ + 25) × 6 = 192 — 거꾸로 192 ÷ 6 = 32, 32 − 25 = 7이에요.","어떤 수는 7이에요.","바르게 계산하면 7 × 6 + 25 = 42 + 25 = 67이에요."]}'::jsonb),
('g5_1_math_u1_L05_basic#1','math',5,1,'u1','L05','g5_1_math_u1_L05_basic','lesson_basic','M5-1-u1-C5',1,'mc','auto','30 − 24 ÷ 6에서 가장 먼저 계산해야 할 것은 어느 것인가요?',ARRAY['M5-1-u1-X04']::text[],true,'{"seq":1,"concept":"M5-1-u1-C5","difficulty":1,"kind":"mc","stem":"30 − 24 ÷ 6에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"24 ÷ 6","correct":true},{"t":"30 − 24","mis":"M5-1-u1-X04"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X04"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","그래서 가장 먼저 계산할 것은 24 ÷ 6이에요.","① 24 ÷ 6 = 4 → ② 30 − 4 = 26이에요."],"variant_rule":{"alt":[{"stem":"18 + 12 ÷ 3에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"12 ÷ 3","correct":true},{"t":"18 + 12","mis":"M5-1-u1-X04"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X04"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","가장 먼저 계산할 것은 12 ÷ 3이에요.","① 12 ÷ 3 = 4 → ② 18 + 4 = 22예요."]},{"stem":"40 − 16 ÷ 4에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"16 ÷ 4","correct":true},{"t":"40 − 16","mis":"M5-1-u1-X04"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X04"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","가장 먼저 계산할 것은 16 ÷ 4예요.","① 16 ÷ 4 = 4 → ② 40 − 4 = 36이에요."]}]}}'::jsonb),
('g5_1_math_u1_L05_basic#2','math',5,1,'u1','L05','g5_1_math_u1_L05_basic','lesson_basic','M5-1-u1-C5',1,'sa','auto','30 − 24 ÷ 6을 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u1-C5","difficulty":1,"kind":"sa","stem":"30 − 24 ÷ 6을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 24 ÷ 6 = 4 → ② 30 − 4 = 26이에요.","그래서 30 − 24 ÷ 6 = 26이에요."],"variant_rule":{"alt":[{"stem":"50 − 32 ÷ 4를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 32 ÷ 4 = 8 → ② 50 − 8 = 42예요.","그래서 50 − 32 ÷ 4 = 42예요."]},{"stem":"27 + 36 ÷ 9를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["31"],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 36 ÷ 9 = 4 → ② 27 + 4 = 31이에요.","그래서 27 + 36 ÷ 9 = 31이에요."]}]}}'::jsonb),
