('g5_1_math_u1_review_b#15','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C6',3,'mc','auto','36 ÷ (6 + 3)과 36 ÷ 6 + 3의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],false,'{"seq":15,"concept":"M5-1-u1-C6","difficulty":3,"kind":"mc","stem":"36 ÷ (6 + 3)과 36 ÷ 6 + 3의 계산 결과의 차는 얼마인가요?","options":[{"t":"5","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"4","mis":"M5-1-u1-X14"},{"t":"9","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","36 ÷ (6 + 3) = 4 · 36 ÷ 6 + 3 = 9","두 결과의 차는 9 − 4 = 5예요."]}'::jsonb),
